export interface CarDetailedDescription {
  id: string;
  fullDescription: string;
  history: string;
  technology: string;
  performance: string;
  design: string;
  luxury: string;
}

export const CAR_DETAILED_DESCRIPTIONS: Record<string, CarDetailedDescription> =
  {
    "Nissan Skyline GT-R R34": {
      id: "1",
      fullDescription: `O Nissan Skyline GT-R R34 é um ícone absoluto da cultura automotiva — um carro que transcendeu gerações, pistas e videogames para se tornar lenda. Sob o capô, o lendário RB26DETT, um seis-cilindros em linha biturbo, entrega potência com enorme margem para preparação, acompanhado do avançado sistema de tração integral ATTESA E-TS, garantindo tração e controle impecáveis.`,
      history: `O R34 é a quinta geração da lina GT-R, sucessor direto do R33. A Nissan desenvolveu o carro com um foco ainda maior em tecnologia, controle e performance, criando um esportivo que fosse extremamente eficiente em pista sem perder a usabilidade nas ruas.\nDurante seu desenvolvimento, a Nissan utilizou muitos aprendizados vindos do automobilismo, especialmente de campeonatos japonses de turismo. O resultado foi um carro mais compacto, mais rígido e mais equilibrado que seu antecessor.`,
      technology: `O Skyline GT-R R34 era incrivelmente avançado para o início dos anos 2000. Um dos destados era o sistema ATTESA E-TS Pro, um sofisticado sistema de tração integral inteligente que distribuía o torque entre os eixos conforme a necessidade, garantindo máxima tração e estabilidade. Outro sistema importante era o Super-HICAS, que permitia esterçamento das rodas traseiras para melhorar a estabilidade em altas velocidades e aumentar a agilidade em curvas.`,
      performance: `O coração do R34 é o lendário motor RB26DETT, um seis cilindros em linha biturbo de 2.6 litros que se torno um dos motores mais respeitados da história automotiva. Mas o grande segredo do RB26 é sua enorme capacidade de preparação. Com modificações relativamente simples, muito preparadores conseguem extrair 600, 800 ou até mais de 100 cv, algo que ajudou a consolidar a fama de carro no mundo do tuning.`,
      design: `O design do R34 é considerado atemporal e extramamente funcional. Ele combina agressividade com simplicidade mecânica. A versão V-Spec também trouxe melhorias aerodinâmicas e suspensão mais rígida para maximizar o desempenho em curvas. Mesmo décadas depois, o R34 ainda é reconhecido instantaneamente por qualquer entusiasta de carros.`,
      luxury: `Apesar de ser um carro focado em performance, o interior do R34 oferece um equilíbrio interessante entre esportivo e conforto. Não é um carro luxuoso no sentido tradicional como um sedã premium, mas transmite uma sensação de qualidade mecânica e engenharia refinada, algo que muitos entusiastas valorizam mais do que luxo convencional.`,
    },
    "Porsche 911 Turbo S": {
      id: "2",
      fullDescription: `O Porsche 911 Turbo S é um dos esportivos mais completos já produzidos. Ele representa décadas de evolução da lendária linhagem 911, combinando engenharia alemã de precisão, desempenho extremo e um nível surpreendente de conforto e sofisticação. Considerado por muitos como o supercarro utilizável no dia a dia, o Turbo S entrega performance comparável a hipercarros enquanto mantém a confiabilidade e a usabilidade características da Porsche.`,
      history: `A história do 911 Turbo começou em 1975, com o lançamento do Porsche 930, o primeiro 911 equipado com turbocompressor. Na época, a Porsche buscava ampliar tecnologias desenvolvidas no automobilismo, especialmente nas corridas de endurance e no campeonato mundial de carros esportivos. Esse primeiro modelo ficou famoso pelo apelido "Widowmaker" (fazedor de viúvas), devido à sua potência elevada e comportamento desafiador. Com o passar das décadas, a Porsche refinou continuamente o conceito, evoluindo aerodinâmica, suspensão, eletrônica e controle de tração.\nO 911 Turbo S moderno, especialmente na geração 992, representa o ápice dessa evolução. Ele mantém a identidade clássica do 911 - motor traseiro e design icônico - mas incopora tecnologias de ponta que o transformam em um dos carros rápidos e equilibrados do mundo.`,
      technology: `O Porsche 911 TUrbo S é conhecido por reunir algumas das tecnologias mais avançadas da engenharia automotiva moderna. Entre os principais sistemas estão:\n\nTração Integral Porsche Traction Management:\nDistribui automaticamente o torque entre os eixos para maximizar tração e estabilidade em qualquer condição.\n\nTransmissão PDK de dupla embreagem:\nA caixa Porsche Doppelkupplun (PDK) realiza trocas de marcha extramamente rápidas, praticamente sem interrupção de potência.\n\nPorsche Active Suspension Management:\nSistema de suspensão adaptativa que ajusta constantemente a rigidez dos amortecedores para equilibrar conforto e performance.\n\nAerodinâmica ativa\nO Turbo S possui spoiler traseiro e elementos aerodinâmincos ajustáveis que aumentam o downforce em altas velocidades.`,
      performance: `O coração do 911 Turbo S é um motor boxer de seis cilindros biturbo, montado na traseira — uma característica histórica da linha 911.\nOs números da Turbo S colocam ela no território de hipercarros, superando muitos superesportivos exóticos em aceleração.\nO mais impressionante, porém, é a facilidade com que ele entrega essa performance. Mesmo com números tão extremos, o carro permanece estável, previsível e controlável, algo que se tornou uma assinatura da engenharia Porsche.`,
      design: `O design do Porsche 911 Turbo S é uma evolução refinada do formato clássico do 911, reconhecido instantaneamente em qualquer lugar do mundo. Linhas arrendondadas e atemporais. Para-lamas traseiros mais largos. Entradas de ar laterais para refrigeração dos turbos. Asa traseira ativa e barra de LED traseira contínua.\n\nApesar de ser extremamente aerodinâmico, o design do Turbo S mantém elegância e equilíbrio visual, evitando exageros comuns em muitos supercarros.`,
      luxury: `Diferente de muitos carros focados exclusivamente em performance, o 911 Turbo S oferece um interior extremamente refinado e tecnológico. O cockpit inclui: acabamento em couro premium. Detalhes em fibra de carbono ou alumínio escovado. Painel digital moderno. Central de multimídia Porsche Communication Management e bancos esportivos extremamente confortáveis.\n\nO isolamento acústico e a qualidade dos materiais fazem com que o Turbo S também funcione perfeitamente como um grand tourer, capaz de realizar longas viagens com conforto e sofisticação.`,
    },
    "Ferrari F8 Tributo": {
      id: `3`,
      fullDescription: `A Ferrari F8 Tributo é um dos supercarros mais emblemáticos da Ferrari na era moderna. Ela representa a essência da engenharia da marca italiana: um carro que combina potência extrema, aerodinâmica refinada e uma experiência de condução visceral. Posicionada como sucessora da 488 GTB, a F8 Tributo foi desenvolvida para celebrar o motor V8 biturbo mais premiado da história da Ferrari. Seu objetivo não era apenas substituir um modelo anterior, mas refinar ao máximo o conceito de supercarro com motor central traseiro, equilibrando desempenho brutal com precisão e controle absoluto.`,
      history: `Lançada oficialmente em 2019, a Ferrari F8 Tributo surgiu como uma homenagem à longa tradição de motores V8 da Ferrari, que ao longo de décadas se tornaram o coração de alguns dos carros esportivos mais lendários da marca. O nome “Tributo” não foi escolhido por acaso: ele simboliza um tributo a essa herança mecânica e tecnológica que começou com modelos como o 308 GTB e evoluiu ao longo dos anos através de carros como o F355, o 360 Modena, o F430 e o 458 Italia.\n\nA F8 Tributo também representa o ponto máximo de evolução do motor V8 biturbo introduzido na Ferrari 488. Ao longo de anos de refinamento e inovação, a Ferrari conseguiu extrair mais potência, eficiência e controle desse conjunto mecânico, criando um supercarro que sintetiza décadas de experiência tanto nas ruas quanto nas pistas.`,
      technology: `A Ferrari F8 Tributo incorpora uma série de tecnologias avançadas desenvolvidas a partir da experiência da marca na Fórmula 1 e em competições de endurance. Um dos destaques é o sistema Side Slip Control, que integra diversos sistemas eletrônicos para gerenciar a dinâmica do carro em curvas, permitindo que o motorista explore o limite do veículo com maior segurança e precisão.\n\nOutro componente importante é o Ferrari Dynamic Enhancer, um sistema que atua no controle de frenagem em curvas para melhorar a estabilidade e o controle durante situações de condução mais agressivas. A aerodinâmica também recebeu grande atenção: a Ferrari redesenhou entradas de ar, difusores e elementos do fluxo de ar para aumentar significativamente o downforce sem aumentar o arrasto.`,
      performance: `No centro da F8 Tributo está um motor V8 biturbo de 3.9 litros, considerado um dos motores mais impressionantes já produzidos pela Ferrari. Ele entrega aproximadamente 720 cavalos de potência, permitindo que o carro acelere de 0 a 100 km/h em cerca de 2,9 segundos e alcance velocidades superiores a 340 km/h.\n\nMas a verdadeira magia da F8 Tributo não está apenas nos números. A resposta do acelerador, o som do motor e a forma como o carro transmite potência ao asfalto criam uma experiência de condução extremamente envolvente. A combinação de peso relativamente baixo, chassi rígido e aerodinâmica avançada permite que o carro mantenha níveis excepcionais de estabilidade mesmo em velocidades muito elevadas.`,
      design: `O design da Ferrari F8 Tributo é ao mesmo tempo elegante e agressivo, refletindo a filosofia da Ferrari de unir beleza e funcionalidade. Cada linha do carro foi desenhada não apenas para impressionar visualmente, mas também para otimizar a aerodinâmica.\n\nA dianteira apresenta entradas de ar amplas e esculpidas que ajudam a canalizar o fluxo de ar para os radiadores e para o sistema aerodinâmico. Na traseira, o carro mantém o clássico conjunto de quatro lanternas circulares, um elemento visual que remete a modelos históricos da Ferrari. A cobertura transparente do motor se tornou um dos detalhes mais marcantes do carro, permitindo visualizar o poderoso V8 que está no coração da máquina.`,
      luxury: `Embora seja um carro claramente focado em desempenho, a Ferrari F8 Tributo também oferece um interior refinado e sofisticado. O cockpit foi projetado para colocar o motorista no centro da experiência, com um layout inspirado em carros de corrida, mas sem abrir mão do conforto e da qualidade dos materiais.\n\nO interior combina couro premium, fibra de carbono e alumínio, criando um ambiente que transmite esportividade e exclusividade. O volante multifuncional integra diversos controles importantes, permitindo que o motorista ajuste configurações do carro sem tirar as mãos do volante.\n\nA ergonomia também foi cuidadosamente estudada para garantir que todos os comandos estejam facilmente acessíveis, reforçando a sensação de conexão entre o motorista e a máquina.`,
    },
    "Lamborghini Huracán EVO": {
      id: `4`,
      fullDescription: `O Lamborghini Huracán EVO representa a evolução de um dos supercarros mais bem-sucedidos da Lamborghini. Desenvolvido para elevar o desempenho, a tecnologia e a experiência de condução do Huracán original, o EVO combina o caráter brutal típico da marca italiana com sistemas eletrônicos avançados que tornam o carro mais inteligente, preciso e conectado ao motorista. Ele foi projetado para oferecer uma experiência de direção extremamente visceral, mas ao mesmo tempo refinada, mantendo a tradição da Lamborghini de criar máquinas que despertam emoção tanto pelo desempenho quanto pela presença visual.`,
      history: `O Huracán EVO foi apresentado em 2019 como uma evolução profunda do Lamborghini Huracán lançado em 2014, modelo que substituiu o lendário Gallardo e se tornou um dos carros mais importantes da história recente da marca. A Lamborghini utilizou tudo o que aprendeu com versões mais radicais, como o Huracán Performante, para criar o EVO, incorporando melhorias significativas em aerodinâmica, eletrônica e dinâmica de condução.\n\nAo longo dos anos, a Lamborghini consolidou sua identidade criando supercarros com motores naturalmente aspirados e design extremamente agressivo. O Huracán EVO continua essa tradição, mantendo o motor V10 aspirado e reforçando o DNA da marca de Sant’Agata Bolognese: carros intensos, dramáticos e projetados para oferecer uma experiência sensorial única ao volante.`,
      technology: `Um dos maiores avanços do Huracán EVO está na tecnologia embarcada. O carro introduziu o sistema Lamborghini Dinamica Veicolo Integrata (LDVI), um cérebro eletrônico que coordena todos os sistemas dinâmicos do veículo em tempo real. Esse sistema analisa constantemente dados como posição do volante, aceleração lateral, velocidade e estilo de condução do motorista para ajustar o comportamento do carro antes mesmo que o motorista perceba a necessidade.\n\nO EVO também conta com sistemas avançados como vetorização de torque, direção nas quatro rodas em algumas versões e controle de tração altamente sofisticado. A aerodinâmica foi significativamente aprimorada em relação ao Huracán original, aumentando o downforce e melhorando a estabilidade em altas velocidades.`,
      performance: `No coração do Huracán EVO está um dos motores mais emocionantes da indústria automotiva: um V10 aspirado de 5.2 litros. Esse motor entrega aproximadamente 640 cavalos de potência, permitindo que o carro acelere de 0 a 100 km/h em cerca de 2,9 segundos e atinja velocidades superiores a 325 km/h.\nA ausência de turbocompressores significa que a resposta do acelerador é instantânea, proporcionando uma sensação extremamente direta entre o motorista e o carro. O som do motor V10 também é um dos aspectos mais marcantes da experiência, produzindo um rugido metálico e agressivo que se intensifica conforme o motor sobe de rotação.\n\nCombinado com a transmissão de dupla embreagem de sete marchas e o sistema de tração integral da Lamborghini, entrega acelerações impressionantes e grande estabilidade.`,
      design: `O design do Huracán EVO segue a filosofia tradicional da Lamborghini: linhas agressivas, formas angulares e uma presença visual que transmite velocidade mesmo quando o carro está parado. Cada elemento do exterior foi cuidadosamente redesenhado em relação ao Huracán original para melhorar a eficiência aerodinâmica e reforçar a identidade visual do modelo.\n\nA dianteira apresenta grandes entradas de ar que ajudam na refrigeração e no gerenciamento do fluxo aerodinâmico. Na traseira, o novo difusor e as saídas de escape posicionadas mais acima reforçam o visual esportivo e contribuem para o desempenho aerodinâmico. A postura baixa, larga e extremamente agressiva do carro cria uma silhueta inconfundível, típica dos supercarros da Lamborghini.`,
      luxury: `Embora seja um supercarro claramente focado em performance, o Huracán EVO também oferece um interior sofisticado e altamente tecnológico. O cockpit foi projetado para envolver o motorista, com um layout inspirado em aviões de combate, característica marcante do design interior da Lamborghini.\n\nO uso de couro premium, Alcantara, fibra de carbono e alumínio cria um ambiente que mistura luxo e esportividade. Os bancos oferecem excelente suporte para condução esportiva, enquanto os acabamentos e detalhes artesanais reforçam o caráter exclusivo do veículo.\n\nAlém disso, a cabine incorpora tecnologia moderna, incluindo painel digital configurável e a central multimídia touchscreen que permite controlar diversas funções do carro.`,
    },
    "Mercedes-AMG GT R": {
      id: `5`,
      fullDescription: `O Mercedes-AMG GT R é um dos carros mais radicais já desenvolvidos pela divisão de performance da Mercedes-Benz. Criado para levar a experiência de um carro de corrida para as ruas, ele representa o ápice da evolução da linha AMG GT em termos de engenharia, desempenho e aerodinâmica. Inspirado diretamente nos carros de competição da marca, o GT R foi projetado para oferecer uma condução extremamente precisa e agressiva, mantendo ao mesmo tempo o refinamento e a qualidade típicos da Mercedes. Seu desenvolvimento teve forte influência das pistas, especialmente do circuito de Nürburgring, um dos ambientes mais exigentes do mundo para testes automotivos.`,
      history: `O Mercedes-AMG GT R foi apresentado em 2016 como a versão mais extrema da família AMG GT até então. Desenvolvido pela equipe da Mercedes-AMG em Affalterbach, o modelo nasceu com o objetivo de aproximar ainda mais os carros de rua da marca da tecnologia utilizada em seus veículos de corrida.\n\nO carro rapidamente ganhou destaque entre os entusiastas e na imprensa automotiva, especialmente por seu desempenho impressionante no lendário circuito de Nürburgring Nordschleife, onde foi amplamente testado durante seu desenvolvimento. Por causa dessa conexão com o circuito alemão e da cor exclusiva de lançamento chamada “Green Hell Magno”, o carro passou a ser conhecido informalmente como “Green Hell Beast”, uma referência ao apelido histórico de Nürburgring, conhecido como “Inferno Verde”.`,
      technology: `O AMG GT R incorpora diversas tecnologias derivadas diretamente do automobilismo. Uma das mais importantes é o sistema de direção nas quatro rodas, que melhora significativamente a agilidade em curvas de baixa velocidade e a estabilidade em altas velocidades.\n\nO carro também conta com aerodinâmica ativa, incluindo um elemento móvel sob o motor que ajusta automaticamente o fluxo de ar para aumentar o downforce quando necessário. Esse tipo de tecnologia normalmente é encontrado apenas em carros de corrida.\n\nOutro destaque é o sistema de suspensão AMG Ride Control, totalmente ajustável, que permite adaptar o comportamento do carro para diferentes tipos de condução — desde uso em estrada até pilotagem em pista.`,
      performance: `No coração do Mercedes-AMG GT R está um poderoso motor V8 biturbo de 4.0 litros, desenvolvido artesanalmente seguindo a filosofia da AMG de “um homem, um motor”. Esse motor produz aproximadamente 585 cavalos de potência, entregando aceleração extremamente rápida e uma experiência de condução intensa.\n\nO carro é capaz de acelerar de 0 a 100 km/h em cerca de 3,6 segundos e alcançar velocidades superiores a 318 km/h. A transmissão automática de dupla embreagem de sete marchas garante trocas rápidas e precisas, enquanto o sistema de tração traseira mantém o caráter esportivo e desafiador típico dos carros de alto desempenho.`,
      design: `O design do AMG GT R reflete claramente sua natureza focada em performance. A dianteira apresenta a icônica grade Panamericana, inspirada nos carros de corrida clássicos da Mercedes, acompanhada por entradas de ar amplas que ajudam a resfriar o motor e otimizar o fluxo aerodinâmico.\n\nA carroceria larga e baixa reforça a postura agressiva do carro, enquanto elementos como o grande aerofólio traseiro fixo, difusor aerodinâmico e detalhes em fibra de carbono contribuem tanto para o visual quanto para a eficiência aerodinâmica.`,
      luxury: `Apesar de sua forte orientação para desempenho, o Mercedes-AMG GT R também oferece um interior sofisticado e refinado. A cabine combina materiais de alta qualidade, como Alcantara, couro premium, fibra de carbono e alumínio, criando um ambiente que mistura luxo e esportividade.\n\nO cockpit é claramente orientado ao motorista, com um console central inspirado em carros de corrida e diversos controles dedicados à dinâmica do veículo. Os bancos esportivos proporcionam excelente suporte lateral, ideal para condução agressiva, mas ainda mantêm o conforto necessário para uso cotidiano.`,
    },
    "Audi R8 V10": {
      id: `6`,
      fullDescription: `O Audi R8 V10 Performance Quattro representa o auge da engenharia esportiva da Audi, combinando tecnologia derivada das pistas com a precisão e sofisticação características da marca alemã. Desenvolvido para entregar uma experiência de condução extremamente envolvente, o R8 é um supercarro que equilibra potência brutal, controle absoluto e usabilidade no dia a dia — algo raro em veículos dessa categoria. Ele é projetado para proporcionar sensações intensas ao volante, mantendo a estabilidade, segurança e refinamento típicos da engenharia da Audi.`,
      history: `O Audi R8 foi apresentado pela primeira vez em 2006, inspirado diretamente no carro de corrida Audi R8 LMS e na experiência da marca nas 24 Horas de Le Mans, competição na qual a Audi conquistou diversas vitórias. Desde o início, o objetivo do projeto era criar um supercarro que combinasse o DNA de competição da marca com tecnologia avançada e confiabilidade para uso nas ruas.\n\nA versão R8 V10 Performance Quattro representa a evolução final da segunda geração do modelo. Ao longo dos anos, o R8 se consolidou como um dos supercarros mais equilibrados do mercado, oferecendo desempenho comparável ao de marcas italianas tradicionais, mas com a precisão e a engenharia meticulosa típicas da Audi.`,
      technology: `O Audi R8 Performance incorpora uma série de tecnologias avançadas voltadas para maximizar desempenho e controle. Um dos elementos centrais é o sistema quattro de tração integral, que distribui a potência de forma inteligente entre as rodas, garantindo máxima aderência em diferentes condições de condução.\n\nOutro destaque é o sistema Audi Drive Select, que permite ajustar diversos parâmetros do carro — como resposta do acelerador, comportamento da suspensão, direção e transmissão — para diferentes modos de condução, desde um uso mais confortável até configurações totalmente voltadas para pista.\n\nNo interior, o carro conta com o Audi Virtual Cockpit, um painel digital totalmente configurável que concentra praticamente todas as informações do veículo, incluindo dados de performance, navegação e telemetria.`,
      performance: `No centro do Audi R8 Performance está um impressionante motor V10 naturalmente aspirado de 5.2 litros, um dos motores mais icônicos da indústria automotiva. Essa unidade produz cerca de 620 cavalos de potência, proporcionando acelerações extremamente rápidas e uma resposta instantânea ao acelerador.\n\nO supercarro é capaz de acelerar de 0 a 100 km/h em aproximadamente 3,1 segundos e atingir velocidades máximas próximas de 331 km/h. A transmissão S tronic de dupla embreagem e sete marchas garante trocas de marcha extremamente rápidas, permitindo que o motor permaneça sempre na faixa ideal de potência.`,
      design: `O design do Audi R8 Performance é uma mistura perfeita de agressividade e elegância tecnológica. As linhas da carroceria são marcantes e aerodinâmicas, com proporções típicas de supercarro: carroceria baixa, larga e com cabine centralizada.\n\nA dianteira apresenta a icônica Singleframe grille da Audi, acompanhada por entradas de ar amplas e faróis afilados que reforçam o visual moderno e esportivo. Na lateral, as side blades, elemento de design característico do R8, ajudam na gestão do fluxo de ar e criam uma identidade visual única.`,
      luxury: `Apesar de ser um supercarro focado em desempenho, o Audi R8 Performance mantém o alto padrão de acabamento típico da marca. O interior combina couro premium, Alcantara, fibra de carbono e alumínio, criando um ambiente sofisticado e esportivo ao mesmo tempo.\n\nO cockpit é totalmente orientado ao motorista, com todos os controles posicionados de forma ergonômica para facilitar o acesso durante a condução esportiva. Os bancos esportivos oferecem excelente suporte lateral, garantindo conforto e estabilidade mesmo em curvas de alta velocidade.`,
    },
    "Bentley Continental GT": {
      id: `7`,
      fullDescription: `O Bentley Continental GT é um dos mais icônicos grand tourers do mundo, combinando luxo extremo, engenharia refinada e desempenho impressionante em um único automóvel. Projetado para longas viagens com máximo conforto e potência abundante, o Continental GT representa perfeitamente a filosofia da Bentley: unir desempenho esportivo com um nível de sofisticação e artesanato que poucos fabricantes conseguem alcançar. O carro oferece uma experiência de condução suave, silenciosa e poderosa, tornando-se uma referência entre os cupês de luxo de alto desempenho.`,
      history: `O Bentley Continental GT foi apresentado pela primeira vez em 2003, marcando uma nova era para a Bentley após a marca passar a fazer parte do grupo Volkswagen. O modelo foi desenvolvido para modernizar a imagem da fabricante britânica e torná-la mais competitiva no segmento de luxo esportivo.\n\nDesde seu lançamento, o Continental GT rapidamente se tornou um dos modelos mais importantes da história da Bentley, ajudando a expandir significativamente a presença global da marca. Ao longo das gerações, o carro evoluiu constantemente, recebendo melhorias em design, tecnologia e desempenho, enquanto mantinha a essência de um verdadeiro grand tourer britânico.`,
      technology: `O Bentley Continental GT incorpora tecnologias modernas projetadas para melhorar tanto o conforto quanto o desempenho. O carro utiliza uma plataforma altamente avançada construída com materiais leves e rígidos, garantindo excelente equilíbrio entre desempenho e refinamento.\n\nEntre os sistemas tecnológicos presentes estão a suspensão adaptativa, que ajusta automaticamente o comportamento do carro de acordo com as condições da estrada e o estilo de condução, além de sistemas avançados de assistência ao motorista e controle dinâmico do veículo.`,
      performance: `Apesar de ser um carro focado em luxo e conforto, o Continental GT também oferece desempenho impressionante. Dependendo da versão, ele pode ser equipado com motores extremamente potentes, como o V8 biturbo de 4.0 litros ou o icônico W12 biturbo de 6.0 litros, ambos capazes de entregar acelerações rápidas e velocidades muito elevadas.\n\nNa versão equipada com o motor W12, o carro pode acelerar de 0 a 100 km/h em cerca de 3,6 segundos, atingindo velocidades máximas superiores a 330 km/h. A tração integral e a transmissão automática de dupla embreagem garantem excelente controle e entrega de potência suave e eficiente.`,
      design: `O design do Bentley Continental GT é uma mistura refinada de elegância clássica e esportividade moderna. A dianteira é dominada pela icônica grade matriz da Bentley, acompanhada por faróis circulares sofisticados que incorporam tecnologia de iluminação avançada.\n\nAs linhas da carroceria são suaves e musculosas ao mesmo tempo, criando uma silhueta equilibrada e extremamente elegante. As proporções do carro — capô longo, cabine recuada e traseira curta — reforçam seu caráter de cupê esportivo de luxo.`,
      luxury: `O interior do Bentley Continental GT é um verdadeiro exemplo de artesanato automotivo britânico. Cada veículo é montado com extremo cuidado, utilizando materiais de altíssima qualidade como couro premium, madeira natural, alumínio polido e detalhes em metal refinado.\n\nOs bancos são extremamente confortáveis e oferecem diversos ajustes elétricos, aquecimento, ventilação e função de massagem, proporcionando uma experiência de viagem extremamente agradável mesmo em trajetos longos.\n\nAlém disso, o nível de personalização disponível é enorme, permitindo que os clientes escolham entre diversas cores, materiais e acabamentos para criar um interior totalmente exclusivo.`,
    },
    "Koenigsegg": {
      id: `8`,
      fullDescription: `O Koenigsegg Regera é um dos hipercarros mais inovadores já criados, projetado para redefinir o conceito de desempenho extremo aliado ao luxo e à tecnologia de ponta. Diferente da maioria dos hipercarros focados exclusivamente em pista, o Regera foi desenvolvido para oferecer uma experiência de condução poderosa, mas ao mesmo tempo refinada e confortável para longas viagens. Seu nome, que significa “reinar” em sueco, representa perfeitamente a proposta do carro: dominar o mundo dos hipercarros com uma combinação inédita de potência, engenharia revolucionária e exclusividade absoluta.`,
      history: `O Regera foi apresentado pela Koenigsegg em 2015, durante o Salão de Genebra, como um projeto que buscava romper com as convenções tradicionais da engenharia automotiva. A marca sueca, fundada por Christian von Koenigsegg, sempre foi conhecida por desafiar limites tecnológicos, e o Regera é talvez o exemplo mais ousado dessa filosofia.\n\nEnquanto outros hipercarros priorizavam transmissões complexas e configurações mecânicas tradicionais, a Koenigsegg decidiu criar algo completamente diferente: um sistema híbrido revolucionário capaz de eliminar a necessidade de uma transmissão convencional. Essa abordagem permitiu criar um carro que entrega potência colossal com suavidade e eficiência inéditas.`,
      technology: `O Koenigsegg Regera é conhecido principalmente por sua tecnologia revolucionária chamada Koenigsegg Direct Drive (KDD). Esse sistema elimina a tradicional caixa de câmbio multi-marchas, substituindo-a por uma solução híbrida inteligente que conecta diretamente o motor ao eixo traseiro em altas velocidades.\n\nO conjunto híbrido combina um motor V8 biturbo de 5.0 litros com três motores elétricos, criando um sistema extremamente sofisticado que entrega potência instantânea e eficiência impressionante. Os motores elétricos auxiliam principalmente em baixas e médias velocidades, garantindo aceleração imediata sem necessidade de trocas de marcha.`,
      performance: `O desempenho do Regera é simplesmente extraordinário. Combinando o motor V8 biturbo com os três motores elétricos, o conjunto gera aproximadamente 1.500 cavalos de potência e mais de 2.000 Nm de torque, números que colocam o carro entre os mais poderosos do planeta.\n\nGraças ao sistema híbrido e ao Direct Drive, a entrega de potência é extremamente suave e contínua. O carro é capaz de acelerar de 0 a 100 km/h em cerca de 2,8 segundos, enquanto a aceleração de 0 a 400 km/h ocorre em um tempo impressionantemente curto para um veículo de produção.`,
      design: `O design do Koenigsegg Regera combina agressividade aerodinâmica com elegância futurista. As linhas da carroceria são fluidas e altamente funcionais, com cada detalhe projetado para melhorar o fluxo de ar e aumentar a estabilidade em altas velocidades.\n\nA dianteira apresenta entradas de ar sofisticadas que auxiliam no resfriamento do sistema híbrido, enquanto a traseira é dominada por um difusor aerodinâmico imenso e um sistema de escapamento central exclusivo. O aerofólio traseiro ativo ajuda a gerar downforce quando necessário, melhorando o controle em altas velocidades.`,
      luxury: `Diferente de muitos hipercarros focados exclusivamente em desempenho, o Regera foi projetado para oferecer um nível elevado de conforto e luxo. O interior apresenta materiais premium como couro de alta qualidade, fibra de carbono exposta, alumínio usinado e acabamentos personalizados, criando um ambiente sofisticado e tecnológico.\n\nOs bancos são confortáveis e projetados para longas viagens, reforçando a proposta do carro como um hipercarro capaz de combinar velocidade extrema com conforto de grand tourer. O sistema multimídia moderno inclui conectividade avançada e diversas funções de controle do veículo.`,
    },
    "BMW M3 Competition": {
      id: `9`,
      fullDescription: `O BMW M3 Competition é a versão mais refinada e potente de um dos sedãs esportivos mais icônicos da história automotiva. Desenvolvido pela divisão BMW M, o modelo combina desempenho de carro de pista com a praticidade e o conforto de um sedã de quatro portas. O M3 sempre foi conhecido por oferecer um equilíbrio excepcional entre potência, precisão de direção e usabilidade diária, e a versão Competition eleva essas qualidades a um novo nível com mais potência, ajustes de chassi aprimorados e tecnologia avançada voltada para performance.`,
      history: `A história do BMW M3 começou em 1986, quando a BMW desenvolveu a primeira geração baseada no BMW Série 3 E30 para homologação em competições de turismo. O carro rapidamente se tornou um ícone entre os entusiastas por sua combinação de agilidade, engenharia precisa e excelente desempenho em pista.\n\nAo longo das décadas, o M3 evoluiu significativamente, passando por diversas gerações — E36, E46, E90/E92, F80 e a atual geração G80. Cada uma trouxe avanços em potência, tecnologia e refinamento, mantendo a essência do modelo como um sedã esportivo extremamente capaz.`,
      technology: `O BMW M3 Competition incorpora uma ampla gama de tecnologias voltadas para maximizar o controle e o desempenho. Entre os principais destaques está o sistema M xDrive (em algumas versões), que oferece tração integral inteligente, permitindo alternar entre modos de condução que priorizam estabilidade ou uma experiência mais esportiva com maior foco na tração traseira.\n\nO carro também conta com o sistema M Drive Professional, que inclui funções como controle de derrapagem ajustável, telemetria para uso em pista e modos de condução personalizáveis que alteram o comportamento do motor, da direção, da suspensão e da transmissão.`,
      performance: `O coração do BMW M3 Competition é um potente motor seis cilindros em linha biturbo de 3.0 litros, conhecido como S58, desenvolvido especificamente pela divisão M. Esse motor produz aproximadamente 510 cavalos de potência e cerca de 650 Nm de torque, proporcionando acelerações extremamente rápidas.\n\nCom essa configuração, o M3 Competition é capaz de acelerar de 0 a 100 km/h em cerca de 3,9 segundos, dependendo da versão e do sistema de tração utilizado. A transmissão automática M Steptronic de oito marchas garante trocas rápidas e eficientes, contribuindo para o desempenho impressionante do carro.`,
      design: `O design do BMW M3 Competition reflete claramente sua natureza esportiva. A dianteira é marcada pela grande grade dupla vertical, um elemento visual que gerou grande discussão entre entusiastas, mas que se tornou uma assinatura marcante da geração atual.\n\nAs linhas da carroceria são musculosas e agressivas, com para-lamas alargados que destacam a postura larga do carro. Elementos aerodinâmicos, entradas de ar ampliadas e detalhes em fibra de carbono reforçam o caráter de alto desempenho do modelo.`,
      luxury: `Embora seja claramente focado em performance, o BMW M3 Competition também oferece um interior sofisticado e confortável. O cockpit combina materiais premium como couro de alta qualidade, fibra de carbono, alumínio escovado e Alcantara, criando um ambiente esportivo e elegante ao mesmo tempo.\n\nOs bancos esportivos oferecem excelente suporte lateral, ideal para condução agressiva, mas também garantem conforto para uso diário. Em algumas versões, estão disponíveis os exclusivos bancos M em fibra de carbono, que reduzem peso e aumentam ainda mais o suporte durante condução esportiva.`,
    },
    "McLaren Senna": {
      id: `10`,
      fullDescription: `O McLaren Senna é um dos hipercarros mais extremos já produzidos para uso em estrada. Desenvolvido com foco absoluto em desempenho em pista, o modelo representa a busca da McLaren pela máxima eficiência aerodinâmica, leveza estrutural e controle dinâmico. Diferente de muitos hipercarros que equilibram luxo e conforto, o Senna foi criado praticamente como um carro de corrida homologado para as ruas. Cada detalhe de seu projeto tem como objetivo melhorar a performance, garantindo uma experiência de condução intensa, precisa e extremamente visceral.`,
      history: `O McLaren Senna foi apresentado em 2018 como parte da linha McLaren Ultimate Series, a categoria mais exclusiva e avançada da marca britânica. O carro recebeu esse nome em homenagem ao lendário piloto brasileiro Ayrton Senna, tricampeão mundial de Fórmula 1 e considerado um dos maiores pilotos da história do automobilismo.\n\nA escolha do nome não foi apenas simbólica: o Senna foi projetado para representar a pureza da performance e da conexão entre piloto e máquina, valores profundamente associados ao estilo de pilotagem de Ayrton Senna. A produção do modelo foi extremamente limitada, com apenas 500 unidades fabricadas, tornando-o rapidamente um dos hipercarros mais exclusivos e desejados do mundo.`,
      technology: `A tecnologia do McLaren Senna gira principalmente em torno de três pilares fundamentais: aerodinâmica, leveza e controle eletrônico avançado. O carro utiliza uma estrutura chamada Monocage III, feita inteiramente de fibra de carbono, que oferece rigidez estrutural extremamente alta ao mesmo tempo que mantém o peso do veículo extremamente baixo.\n\nOutro destaque é o sofisticado pacote aerodinâmico ativo. O enorme aerofólio traseiro ajustável, o difusor traseiro gigante e diversos elementos aerodinâmicos distribuídos pela carroceria trabalham juntos para gerar níveis impressionantes de downforce. Em altas velocidades, o Senna pode gerar mais de 800 kg de pressão aerodinâmica, mantendo o carro extremamente estável em curvas rápidas.`,
      performance: `No coração do McLaren Senna está um poderoso motor V8 biturbo de 4.0 litros, desenvolvido para entregar desempenho brutal e resposta imediata ao acelerador. Esse motor produz aproximadamente 800 cavalos de potência e cerca de 800 Nm de torque, números que colocam o carro entre os mais rápidos do mundo.\n\nCombinado a uma transmissão de dupla embreagem de sete marchas, o Senna é capaz de acelerar de 0 a 100 km/h em cerca de 2,8 segundos e atingir velocidades superiores a 335 km/h.`,
      design: `O design do McLaren Senna é totalmente orientado pela função. Cada elemento da carroceria foi projetado para maximizar a eficiência aerodinâmica e o fluxo de ar ao redor do carro. Isso resulta em uma aparência extremamente agressiva e técnica, onde praticamente todas as superfícies têm uma função aerodinâmica específica.\n\nA dianteira apresenta entradas de ar grandes e complexas que direcionam o fluxo de ar para resfriamento e geração de downforce. As laterais possuem superfícies esculturais que ajudam a canalizar o ar para o difusor traseiro.`,
      luxury: `Apesar de ser um carro focado quase exclusivamente em performance, o McLaren Senna ainda apresenta um nível de acabamento refinado. O interior segue uma filosofia minimalista, removendo tudo o que não seja essencial para reduzir peso e aumentar a concentração do motorista.\n\n`,
    },
    "Ford Mustang GT Performance": {
      id: "11",
      fullDescription: `O Ford Mustang GT Performance representa a evolução moderna do muscle car americano mais icônico. Desde 1964, o Mustang definiu o segmento dos pony cars. A versão GT Performance combina o lendário motor V8 Coyote com tecnologia de ponta, criando um esportivo que honra suas raízes enquanto compete com supercarros europeus modernos.`,
      history: `O Ford Mustang revolucionou a indústria em 1964 apresentado por Lee Iacocca. Vendeu 22.000 unidades no primeiro dia e um milhão em 18 meses. Ao longo de sete gerações, sobreviveu à crise do petróleo e ressurgiu com força no século XXI. A geração atual representa equilíbrio entre tradição americana e tecnologia contemporânea.`,
      technology: `Sistema MagneRide lê a estrada 1.000 vezes por segundo ajustando amortecimento. Line Lock trava rodas dianteiras aquecendo pneus. Launch Control otimiza tração. Pacote Performance inclui diferencial Torsen, freios Brembo e calibração de estabilidade esportiva.`,
      performance: `Motor Coyote V8 5.0L: 460cv e 569Nm. Resposta instantânea sem lag. Comando de válvulas independente gera potência até 7.500rpm. Manual Tremec 6 marchas ou automática 10 velocidades. 0-100 km/h em 4.3s.`,
      design: `Design agressivamente americano com linhas musculosas. Dianteira dominada pela grade trapezoidal e faróis tri-bar LED. Capô com extração de ar funcional. Proporções perfeitas: capô longo, habitáculo recuado. Teto fastback. Rodas 19", difusor traseiro, quatro saídas de escape.`,
      luxury: `Bancos Recaro em couro perfurado. Volante base plana em couro/Alcantara. Painel TFT 12" customizável com G-forces e temperatura. SYNC 3 com tela 8" integra CarPlay/Android Auto. Som B&O 12 alto-falantes compete com rugido do V8.`,
    },

    "Bugatti Chiron Sport": {
      id: "12",
      fullDescription: `O Bugatti Chiron Sport é evolução do hipercarro mais rápido do mundo, focando em agilidade sem sacrificar 1.500cv. Enquanto o Chiron standard prioriza velocidade máxima, o Sport oferece dinâmica aprimorada em circuitos sinuosos.`,
      history: `Chiron Sport nasceu do Veyron que ultrapassou 400 km/h em 2005. Lançado em 2018 do feedback de clientes desejando agilidade. Engenheiros refinaram suspensão, reduziram peso e recalibraram direção para dominar curvas técnicas de Nürburgring.`,
      technology: `Tecnologia aeroespacial: 10 radiadores dedicados. Chassi fibra de carbono autoclave. Suspensão adaptativa lê estrada ajustando em milissegundos. Freios carbono-silício param de 400 km/h em <10s.`,
      performance: `1.500cv a 6.700rpm, 1.600Nm entre 2.000-6.000rpm. 0-100 km/h: 2.4s, 0-200: 6.1s, 0-300: 13.1s. Pneus Michelin Pilot Sport Cup 2 especiais suportam 420+ km/h.`,
      design: `Forma segue função extrema. Ferradura Bugatti canaliza ar para radiadores. Linha C divide carro em duas cores. Spoiler traseiro estende-se verticalmente gerando 400kg de força em frenagens. Difusor trabalha com assoalho plano.`,
      luxury: `Couro premium costurado à mão. Alumínio sólido usinado e fibra carbono. Som Accuton com alto-falantes diamante. Programa Sur Mesure: personalização ilimitada, cores exclusivas, nome gravado em alumínio.`,
    },

    "Aston Martin Vantage": {
      id: "13",
      fullDescription: `O Aston Martin Vantage é entrada acessível em supercarros britânicos, mas é esportivo puro-sangue para emocionar. Menor que DB11, foca em precisão dinâmica. Motor AMG e chassi Aston Martin combinam brutalidade alemã com elegância britânica.`,
      history: `Nome Vantage desde 1951 denota alta performance. Modelo atual (2018) marca nova era pós-parceria Mercedes-AMG. Fundada em 1913, ganhou fama como carro de James Bond desde 1964. Vantage moderno honra tradição incorporando tecnologia alemã.`,
      technology: `Plataforma alumínio VH: rigidez excepcional, peso controlado. Suspensão Skyhook ajusta amortecimento equilibrando conforto/controle. Diferencial E-Diff distribui torque traseiro. Três modos (Sport, Sport+, Track) transformam caráter do carro.`,
      performance: `V8 biturbo 4.0L AMG recalibrado Aston: 510cv, 685Nm. 0-100 km/h: 3.5s, máxima 314 km/h. Motor atrás eixo dianteiro: distribuição peso 50:50. Som V8 visceral: ronco grave evolui para grito metálico.`,
      design: `Agressivamente belo: sensualidade britânica com postura predador. Grade côncava/convexa, faróis afilados. Capô com Aeroblade melhora refrigeração/downforce. Flancos musculosos, entradas ar laterais. Spoiler retrátil acima 80 km/h.`,
      luxury: `Couro Bridge of Weir escocês premium. Volante base plana couro/Alcantara. Painel TFT 12" configurável. Programa Q: personalização extensiva - qualquer cor couro, padrão costura, materiais.`,
    },

    "Dodge Charger SRT Hellcat": {
      id: "14",
      fullDescription: `O Dodge Charger SRT Hellcat é brutalidade americana em quatro portas. Sedã muscle car combina 707cv supercharged com espaço para cinco adultos. Prova que muscle cars evoluíram para forma prática sem perder essência selvagem.`,
      history: `Nome Charger desde 1966 (cupê fastback). Ressurgiu 2006 como sedã quatro portas. SRT Hellcat (2015) elevou a níveis absurdos. Supercharger 2.4L sobre V8 Hemi rivaliza hipercarros mas em pacote familiar prático e acessível.`,
      technology: `Supercharger IHI 2.4L gira 14.600rpm forçando ar 11.6psi. Refrigeração robusta: intercooler massivo, múltiplos radiadores. Suspensão Bilstein adaptativa. Brembo 6 pistões dianteiros/4 traseiros. AWD opcional melhora lançamentos.`,
      performance: `Hemi V8 supercharged 6.2L: 707cv, 881Nm. 0-100 km/h: 3.6s (sedã 2 toneladas!). Máxima limitada 315 km/h. Automática TorqueFlite 8 velocidades. Launch Control. Consumo terrível mas ninguém compra por eficiência.`,
      design: `Agressivamente muscular. Grade massiva alimenta supercharger. Capô com scoop funcional. Detalhes bronze: badges Hellcat, rodas forjadas 20". Arcos roda alargados para pneus largos. Spoiler discreto, quatro saídas escape sonoras.`,
      luxury: `Bancos Nappa/Alcantara com aquecimento/ventilação. Volante base plana couro perfurado. Uconnect tela 8.4" com CarPlay/Android Auto. Performance Pages: dados tempo real (potência, torque, G-forces). Som Harman Kardon 19 alto-falantes.`,
    },

    "Chevrolet Corvette C8 Stingray": {
      id: "15",
      fullDescription: `O Chevrolet Corvette C8 Stingray é revolução: primeira vez em 67 anos abandona motor dianteiro para mid-engine. Mudança transforma Corvette de muscle car em supercarro legítimo que rivaliza modelos custando 3x mais.`,
      history: `Corvette nasceu 1953 resposta a roadsters europeus. Sete gerações mantiveram motor dianteiro. Rumores mid-engine desde anos 60 realizaram-se em 2020. Zora Arkus-Duntov sonhava com mid-engine desde 60s. Décadas depois, visão democratizou velocidade extrema.`,
      technology: `Chassi projetado zero para mid-engine. Alumínio: rigidez torsional excepcional. Motor central baixa centro gravidade: distribuição peso 40:60. Suspensão Magnetic Ride Control. Performance Traction Management integra tração/estabilidade/diferencial. Cinco modos condução.`,
      performance: `LT2 V8 6.2L aspirado: 495cv, 637Nm. DCT dupla embreagem 8 velocidades: trocas 100ms. 0-100 km/h: 2.9s com Z51 Package. Launch Control otimiza saída. Máxima 312 km/h. Supercarro legítimo, não muscle car rápido.`,
      design: `Radicalmente diferente. Silhueta mid-engine: habitáculo recuado, capô curto, deck longo. Linhas angulares, entradas ar agressivas. Traseira dramática: lanternas quad LED, quatro saídas escape centrais. Teto removível vira targa.`,
      luxury: `Interior alcança padrão premium. Orientado motorista, controles ergonômicos. Tela touchscreen 12" responsiva: CarPlay/Android Auto wireless. Painel digital 12" configurável. Bancos GT2 opcionais. Couro Nappa, fibra carbono, alumínio. Qualidade supera gerações.`,
    },

    "Ford GT": {
      id: "16",
      fullDescription: `O Ford GT existe por razão singular: vencer Le Mans. Desenvolvido para dominar classe GTE Pro, versão rua é homologação para competir. Exercício puro engenharia corrida aplicada à estrada, sem concessões a conforto.`,
      history: `História remonta rivalidade Ford vs Ferrari anos 60. Enzo cancelou venda Ferrari para Ford (1963), Henry Ford II jurou vingança. Resultado: GT40 dominou Le Mans 1966-1969. GT moderno (2016) celebra 50 anos primeira vitória. Vitória 2016 validou conceito. 1.350 unidades mantém exclusividade.`,
      technology: `Chassi monocoque fibra carbono: obra-prima leve (1.385kg). Manufatura aeroespacial. Aerodinâmica ativa: spoiler ajusta-se automaticamente. Suspensão pushrod inboard: tecnologia F1. Freios carbocerâmicos massivos trabalham com aerodinâmica.`,
      performance: `EcoBoost V6 3.5L biturbo: 660cv, 746Nm. Turbos eliminam lag: geometria cuidadosa, gerenciamento eletrônico. DCT 7 velocidades instantâneo. 0-100 km/h: 3.0s, máxima 348 km/h. Downforce 180kg a máxima mantém carro colado, permitindo curvas absurdas.`,
      design: `Totalmente ditado por aerodinâmica. Teto baixo flui até spoiler ativo. Entradas ar laterais massivas alimentam intercoolers/radiadores. Túneis ar geram efeito Venturi. Portas tesoura. Para-brisas inclinado, janelas mínimas reduzem resistência. Beleza é consequência eficiência.`,
      luxury: `Minimalista por necessidade. Habitáculo cabe capacete corrida. Bancos fixos; pedais/volante movem-se para motorista. Acabamento impecável. Alcantara cobre superfícies. Fibra carbono exposta. Volante base plana Alcantara perfeito. Som? V6 turbo rugindo atrás.`,
    },

    "Volkswagen Golf R": {
      id: "17",
      fullDescription: `O Volkswagen Golf R é ápice engenharia hot hatch, equilibrando performance explosiva com praticidade diária. Golf que ganhou músculos mas busca crianças na escola. Síntese perfeita versatilidade alemã.`,
      history: `Linhagem R começou 2009 sucessor R32. VW reconheceu demanda por Golf mais potente que GTI. Golf sempre foi base experimentos alta performance. GTI original 1976 criou categoria hot hatch, R32 motor VR6, até R atual: turbo 4 cilindros mais potente história Golf. 50 anos conhecimento carros pequenos absurdamente rápidos.`,
      technology: `4Motion AWD: embreagem Haldex quinta geração distribui torque instantaneamente. Envia até 100% torque traseiro quando necessário. Suspensão DCC: 15 configurações amortecimento. Modo Race desativa eletrônicos quase totalmente. Diferencial XDS melhora curvas via frenagem seletiva.`,
      performance: `EA888 2.0L turbo: 320cv, 420Nm - extraordinários para 4 cilindros. Turbo baixa inércia elimina lag. 0-100 km/h: 4.7s. DSG dupla embreagem 7 velocidades absurdamente rápida. Launch Control. Máxima limitada 250 km/h (opcional 270 km/h).`,
      design: `Sutileza agressiva. Baseado Golf standard: para-choques únicos, entradas ar maiores, spoiler discreto funcional, quatro saídas escape. Rodas forjadas 19". Detalhes azul: logos R, pinças freio. Capô com nervuras sugere potência. Lobo em pele cordeiro perfeito.`,
      luxury: `Bancos esportivos Nappa/Alcantara: suporte excepcional. Volante base plana couro perfurado. Digital Cockpit Pro 10.25" configurável: modo dados performance. Infotainment tela 10" com navegação/conectividade. Qualidade materiais/montagem VW: impecável.`,
    },

    "Lexus LS 500": {
      id: "18",
      fullDescription: `O Lexus LS 500 representa luxo japonês elevado à arte. Sedã flagship combina híbrido avançado, artesanato takumi, atenção obsessiva a detalhes. Alternativa zen a sedãs alemães, oferece refinamento absoluto e confiabilidade lendária Toyota.`,
      history: `LS revolucionou indústria quando lançado 1989 como LS 400. Toyota criou Lexus para competir S-Class/Série 7. Primeira geração estabeleceu padrão novo refinamento/confiabilidade. Quinta geração (2017): mudança dramática. Plataforma GA-L nova, design ousado, foco experiência sensorial total.`,
      technology: `LS 500: V6 3.5L biturbo com automática 10 velocidades. LS 500h: híbrido Multi-Stage. Suspensão pneumática adaptativa lê estrada via câmera detectando irregularidades antes de alcançá-las. Safety System+ 2.0: toda assistência disponível - cruzeiro adaptativo, centralização faixa, detecção pedestres, matriz LEDs adaptativos.`,
      performance: `V6 biturbo: 416cv, 600Nm. Potência chega suavemente, sem drama. 0-100 km/h: 4.9s mas sensação é inevitabilidade suave. Híbridos: V6 aspirado+elétrico, potência similar, eficiência superior. Transição modos imperceptível. Não é para pistas - devora continentes em silêncio absoluto.`,
      design: `Ousado para Lexus. Grade spindle massiva domina dianteira: polarizante mas inconfundível. Linhas caráter afiadas fluem laterais musculosas. Proporções perfeitas: capô longo, habitáculo espaçoso, deck curto. Maçanetas retráteis, iluminação ambiente 28 cores. Design cresce com tempo.`,
      luxury: `Filosofia omotenashi (hospitalidade japonesa). Artesãos takumi (25+ anos) montam cada veículo. Couro semi-aniline suave. Madeira Shimamoku fatias finas revelam grão tridimensional. Bancos massagem shiatsu 28 ajustes. Isolamento acústico obsessivo: vidros triplos, espumas multicamadas. Mark Levinson 23 alto-falantes.`,
    },

    "Toyota Camry": {
      id: "19",
      fullDescription: `O Toyota Camry representa confiabilidade elevada à perfeição. Sedã médio domina EUA décadas via fórmula simples: qualidade impecável, custo propriedade baixo, refinamento constante. Escolha pragmática que raramente decepciona.`,
      history: `Camry nasceu 1982 sedã compacto, evoluiu médio 1991. Nome deriva kanmuri japonês: coroa. Gerações refinaram fórmula sem mudanças radicais. Geração atual XV70 (2017): mudança significativa. Plataforma TNGA: direção precisa, suspensão aprimorada, design ousado. Confiabilidade sozinha insuficiente - Camry precisava ser desejável.`,
      technology: `TNGA: centro gravidade baixo, rigidez torsional +30%. Suspensão independente redesenhada: equilíbrio conforto/controle. Safety Sense 2.0 standard: cruzeiro adaptativo, centralização faixa, detecção pedestres/ciclistas, faróis automáticos. Híbridos: Hybrid Synergy Drive refinado 2 décadas.`,
      performance: `Três powertrains: 2.5L (203cv), 3.5L V6 (301cv), 2.5L híbrido (208cv). V6 surpreendente: 0-100 km/h 5.8s. Automática 8 velocidades suave/responsiva. Híbrido: 5.3L/100km urbano - impressionante para sedã. Transição modos imperceptível: marca Toyota.`,
      design: `Ousado para padrões conservadores. Dianteira agressiva: grade larga, faróis afilados. Linhas caráter pronunciadas laterais. Traseira limpa: lanternas LED conectadas barra cromada. Proporções equilibradas. Rodas até 19". Design envelhece bem: sólido, apropriado.`,
      luxury: `Prioriza funcionalidade sobre ostentação. Layout ergonômico: controles lógicos. Bancos confortáveis longas viagens. Materiais duráveis: plásticos alta qualidade resistem anos. Infotainment tela até 9" com CarPlay/Android Auto. JBL 9 alto-falantes surpreendente. Espaço traseiro generoso: 965mm pernas. Satisfaz diariamente por década.`,
    },

    "Rolls-Royce Phantom": {
      id: "20",
      fullDescription: `O Rolls-Royce Phantom é expressão máxima luxo automotivo, ápice absoluto artesanato/tecnologia/exclusividade. Não é simplesmente carro - é declaração conquista suprema, símbolo status transcende indústria. Phantom existe categoria própria, incomparável, inigualável.`,
      history: `Nome Phantom desde 1925 estabeleceu padrão luxo. Século mantém filosofia: criar melhor carro mundo, custo irrelevante. Oitava geração (2017): 5 anos desenvolvimento. Cada Phantom demora 450h construção Goodwood, Inglaterra. Mestres artesãos décadas experiência montam individualmente.`,
      technology: `Architecture of Luxury alumínio exclusiva Phantom. Rigidez estrutural excepcional: isolamento acústico absoluto - 100 km/h cabine mais silenciosa biblioteca. Suspensão pneumática auto-nivelante lê estrada via câmera ajustando preventivamente. Direção quatro rodas melhora manobrabilidade 5.76m comprimento.`,
      performance: `V12: 571cv, 900Nm mas Rolls nunca enfatiza números. Aceleração "adequada" - eufemismo britânico extraordinariamente rápida. 0-100 km/h: 5.4s (absurdo 2.560kg). Automática ZF 8 velocidades calibrada invisibilidade: trocas imperceptíveis. Phantom não acelera; avança majestosamente. Máxima limitada 250 km/h: acadêmica.`,
      design: `Atemporal por intenção. Proporções majestosas: capô imenso V12, cabine espaçosa, deck dignificado. Grade Pantheon icônica, faróis laser 600m. Spirit of Ecstasy retrátil surge capô. Portas coach traseiras entrada régia. Rodas 22" maiores carros compactos. Cada Phantom único: Bespoke personalização ilimitada.`,
      luxury: `Transcende descrições. Gallery: painel envidraçado dashboard, arte customizada. Couro: touros altitudes elevadas sem cerca arame, pele perfeita. Madeira livro único: grão espelhado. 130kg isolamento acústico: silêncio absoluto. Som Bespoke 18 alto-falantes calibrado Abbey Road Studios. Luxo sem compromissos, limites, igual.`,
    },

    "BMW M5 Competition": {
      id: "21",
      fullDescription: `O BMW M5 Competition é a personificação do equilíbrio entre luxo executivo e desempenho extremo. Trata-se de um sedã que, à primeira vista, pode passar despercebido, mas que esconde sob sua aparência elegante uma capacidade dinâmica comparável à de supercarros. Desenvolvido pela divisão BMW M, o modelo foi projetado para entregar uma experiência de condução intensa e precisa, sem abrir mão do conforto, tecnologia e sofisticação esperados de um carro de alto padrão.`,
      history: `A linhagem do BMW M5 começou em 1984, com o lançamento do primeiro modelo baseado no Série 5 E28. Desde então, o M5 se consolidou como referência absoluta no segmento de sedãs de alta performance, sendo constantemente evoluído ao longo das gerações.\n\nA versão Competition surgiu como uma evolução ainda mais agressiva dentro da linha M5, trazendo ajustes mais refinados de suspensão, maior rigidez estrutural e aumento de potência. Na geração F90, o M5 passou a adotar tração integral inteligente, marcando uma mudança importante na filosofia do modelo, que historicamente era conhecido por sua tração traseira. Essa evolução permitiu que o carro atingisse níveis ainda mais altos de desempenho, sem comprometer a dirigibilidade.`,
      technology: `O BMW M5 Competition incorpora uma série de tecnologias avançadas focadas em desempenho e controle. Um dos principais destaques é o sistema M xDrive, que permite alternar entre diferentes modos de tração, incluindo configurações com foco em tração integral ou comportamento predominantemente traseiro, oferecendo versatilidade tanto para uso cotidiano quanto para condução esportiva.`,
      performance: `O coração do BMW M5 Competition é um poderoso motor V8 biturbo de 4.4 litros, capaz de gerar aproximadamente 625 cavalos de potência e cerca de 750 Nm de torque. Essa configuração permite ao sedã acelerar de 0 a 100 km/h em cerca de 3,3 segundos, números que o colocam no território de supercarros.\n\nO mais notável é a forma como o carro consegue combinar essa performance extrema com controle e previsibilidade, tornando-se acessível tanto para motoristas experientes quanto para uso diário.`,
      design: `O design do BMW M5 Competition mantém a elegância característica da Série 5, mas com elementos que destacam seu caráter esportivo. A dianteira apresenta a tradicional grade dupla da BMW, acompanhada por entradas de ar maiores e detalhes em acabamento escurecido, exclusivos da versão Competition.\n\nA carroceria possui linhas limpas e musculosas, com para-lamas levemente alargados que reforçam a postura robusta do carro. Na traseira, o destaque fica para o difusor esportivo e o sistema de quatro saídas de escape, marca registrada dos modelos M.`,
      luxury: `O interior do BMW M5 Competition oferece um ambiente sofisticado e altamente tecnológico. Materiais premium como couro Merino, fibra de carbono, alumínio e Alcantara são utilizados em todo o acabamento, proporcionando uma sensação de luxo e exclusividade.\n\nOs bancos esportivos oferecem excelente suporte lateral, ao mesmo tempo em que garantem conforto para longas viagens. O espaço interno é amplo, permitindo que o carro seja utilizado tanto como um esportivo quanto como um sedã executivo.`,
    },

    "Audi RS6 Avant Performance": {
      id: "22",
      fullDescription: `O Audi RS6 Avant Performance é a definição perfeita de um carro que desafia categorias. Ele combina a praticidade de uma perua com o desempenho de um supercarro, criando um dos veículos mais versáteis e impressionantes da atualidade. Desenvolvido pela divisão Audi Sport, o RS6 Avant Performance entrega potência brutal, tecnologia avançada e um nível elevado de conforto, sendo capaz de atender tanto ao uso familiar quanto a uma condução extremamente esportiva. É um carro que surpreende justamente por unir extremos que raramente coexistem.`,
      history: `A linhagem RS6 começou no início dos anos 2000, quando a Audi decidiu levar o conceito de perua esportiva a um novo patamar. Desde então, o modelo se tornou um ícone entre entusiastas, especialmente por manter a carroceria Avant — algo raro em carros de alto desempenho.\n\nA versão Performance representa o refinamento máximo da geração atual (C8), trazendo melhorias em potência, resposta do motor e ajustes dinâmicos. Ao longo dos anos, o RS6 construiu uma reputação sólida por oferecer desempenho de alto nível com a praticidade de um carro familiar, tornando-se uma referência absoluta no segmento.`,
      technology: `O Audi RS6 Avant Performance incorpora tecnologias avançadas que trabalham em conjunto para oferecer controle e eficiência em qualquer situação. O sistema quattro de tração integral é um dos pilares do carro, garantindo aderência excepcional e distribuição inteligente de torque entre as rodas.\n\nOutro destaque é a presença da suspensão adaptativa RS, que ajusta continuamente o comportamento do carro de acordo com o modo de condução selecionado. O sistema Audi Drive Select permite configurar parâmetros como resposta do motor, direção, suspensão e transmissão, adaptando o carro tanto para conforto quanto para performance extrema.`,
      performance: `Debaixo do capô, o RS6 Avant Performance abriga um poderoso motor V8 biturbo de 4.0 litros, capaz de entregar aproximadamente 630 cavalos de potência e cerca de 850 Nm de torque. Esse conjunto permite que o carro acelere de 0 a 100 km/h em cerca de 3,4 segundos, números impressionantes para um veículo desse porte.\n\nA transmissão automática de oito marchas trabalha em conjunto com o sistema quattro para garantir aceleração rápida e eficiente, enquanto o sistema híbrido leve (mild-hybrid) contribui para melhorar a resposta e a eficiência do conjunto.`,
      design: `O design do Audi RS6 Avant Performance é agressivo e imponente, mantendo ao mesmo tempo a elegância característica das peruas da marca. A carroceria é significativamente mais larga que a de um A6 convencional, com para-lamas alargados que reforçam sua presença esportiva.\n\nA dianteira é dominada pela Singleframe grille em acabamento escurecido, acompanhada por entradas de ar amplas e detalhes aerodinâmicos marcantes. Na traseira, o difusor esportivo e as grandes saídas de escape ovaladas reforçam o caráter de alto desempenho do modelo.`,
      luxury: `O interior do Audi RS6 Avant Performance oferece um ambiente sofisticado e altamente tecnológico. Materiais como couro premium, Alcantara, fibra de carbono e alumínio escovado são amplamente utilizados, criando uma cabine refinada e esportiva ao mesmo tempo.\n\nOs bancos esportivos RS oferecem excelente suporte lateral, ideais para condução mais agressiva, mas também garantem conforto em viagens longas. O espaço interno generoso e o amplo porta-malas reforçam a praticidade do modelo, tornando-o um verdadeiro carro para todas as situações.`,
    },

    "Nissan Silvia S15 Spec-R": {
      id: "23",
      fullDescription: `O Nissan Silvia S15 Spec-R é um dos esportivos japoneses mais cultuados de todos os tempos, conhecido por seu equilíbrio excepcional, leveza e enorme potencial para preparação. Lançado no fim da era de ouro dos esportivos japoneses, o S15 representa a forma mais refinada da linhagem Silvia, combinando design agressivo, mecânica confiável e uma dirigibilidade que o tornou referência tanto nas ruas quanto no mundo do drift. É um carro que conquistou status lendário entre entusiastas por oferecer uma experiência de condução pura e altamente conectada ao motorista.`,
      history: `O Silvia S15 foi lançado em 1999 como a última geração da linha Silvia, uma família de cupês esportivos que começou ainda nos anos 60, mas ganhou grande notoriedade a partir das gerações S13 e S14. O S15 foi desenvolvido com foco em melhorar a rigidez estrutural, a resposta dinâmica e a performance geral, consolidando-se como o ápice dessa evolução.\n\nA versão Spec-R era a mais voltada para desempenho, equipada com melhorias significativas em relação à versão Spec-S, incluindo motor turbo, diferencial de deslizamento limitado e componentes mais robustos. Apesar de seu sucesso, o S15 teve produção relativamente curta, encerrada em 2002, o que contribuiu para sua raridade e valorização ao longo dos anos.`,
      technology: `Embora não seja um carro repleto de eletrônica avançada como modelos modernos, o Silvia S15 Spec-R traz tecnologias importantes para sua época, focadas principalmente em desempenho e dirigibilidade. Ele conta com um diferencial de deslizamento limitado (LSD), essencial para melhorar a tração e o controle em curvas, especialmente em condução esportiva e drift.\n\nA suspensão foi refinada para oferecer melhor estabilidade e resposta, enquanto a distribuição de peso equilibrada contribui para o comportamento dinâmico previsível e preciso. O carro também apresenta um chassi relativamente leve e rígido, o que melhora significativamente a agilidade.`,
      performance: `O coração do Silvia S15 Spec-R é o lendário motor SR20DET, um quatro cilindros turbo de 2.0 litros que se tornou um dos motores mais respeitados da indústria automotiva japonesa.\n\nNa versão Spec-R, esse motor entrega aproximadamente 250 cavalos de potência, com excelente resposta e uma faixa de torque bem utilizável. O carro pode acelerar de 0 a 100 km/h em cerca de 5,5 segundos, números bastante competitivos para sua época.\n\nA tração traseira, combinada com o baixo peso e o equilíbrio do chassi, torna o S15 extremamente divertido de dirigir. Ele oferece uma experiência direta e envolvente, sendo particularmente valorizado por sua capacidade de manter controle em situações de derrapagem — característica que o tornou um dos carros favoritos no drift.`,
      design: `O design do Nissan Silvia S15 é frequentemente considerado um dos mais bonitos entre os esportivos japoneses dos anos 90 e início dos 2000. Ele apresenta linhas agressivas e bem definidas, com uma dianteira baixa e faróis afilados que dão ao carro uma aparência moderna e esportiva.\n\nA traseira é marcada por lanternas horizontais elegantes, enquanto a silhueta geral do carro mantém proporções clássicas de um cupê esportivo com tração traseira. O conjunto transmite leveza e agilidade, refletindo perfeitamente o comportamento dinâmico do veículo.`,
      luxury: `O interior do Silvia S15 Spec-R segue uma proposta simples e funcional, com foco total na condução. Embora não seja um carro luxuoso no sentido tradicional, ele oferece um ambiente bem construído, com materiais de qualidade e ergonomia voltada ao motorista.\n\nOs bancos esportivos proporcionam bom suporte lateral, e o painel apresenta um layout limpo e intuitivo, facilitando o acesso aos controles durante a condução esportiva. A experiência dentro do carro é mais voltada para a conexão com a máquina do que para conforto excessivo.`,
    },

    "Volkswagen Arteon Shooting Brake R": {
      id: "24",
      fullDescription: `O Volkswagen Arteon Shooting Brake R é a combinação perfeita entre elegância europeia, versatilidade de uma perua e desempenho esportivo de alto nível. Ele representa o lado mais sofisticado e ousado da Volkswagen, trazendo um design refinado aliado à engenharia da divisão R, responsável pelos modelos mais esportivos da marca. Diferente de um esportivo tradicional, o Arteon R entrega potência e dinamismo sem abrir mão do conforto e da praticidade, tornando-se um verdadeiro grand tourer moderno com alma esportiva.`,
      history: `O Arteon surgiu como sucessor espiritual do Passat CC, com a proposta de oferecer um modelo mais premium dentro da linha Volkswagen. Com o tempo, a marca expandiu o conceito para incluir a versão Shooting Brake, uma perua de perfil esportivo muito popular na Europa.\n\nA introdução da versão R marcou um novo capítulo na história do modelo, trazendo o know-how da Volkswagen R para um carro que até então era mais voltado ao luxo e conforto. Essa união criou um veículo que mantém a elegância e a sofisticação do Arteon, mas com um desempenho muito mais agressivo e envolvente, posicionando-o como uma alternativa única no mercado.`,
      technology: `O Arteon Shooting Brake R é equipado com tecnologias avançadas que elevam tanto o desempenho quanto o conforto. Um dos grandes destaques é o sistema de tração integral 4Motion com R-Performance Torque Vectoring, que distribui o torque de forma inteligente entre as rodas traseiras, permitindo maior precisão em curvas e até um comportamento mais dinâmico em condução esportiva.\n\nO carro também conta com o sistema Driving Profile Selection, que permite ajustar diversos parâmetros como motor, suspensão adaptativa (DCC), direção e transmissão, adaptando o veículo para diferentes estilos de condução.`,
      performance: `Sob o capô, o Arteon Shooting Brake R utiliza um motor 2.0 TSI turbo, capaz de entregar cerca de 320 cavalos de potência e aproximadamente 420 Nm de torque. Esse conjunto permite que o carro acelere de 0 a 100 km/h em cerca de 4,9 segundos, números impressionantes para uma perua.\n\nA transmissão automática de dupla embreagem (DSG) garante trocas rápidas e suaves, enquanto o sistema 4Motion assegura máxima tração em diferentes condições. O resultado é um carro extremamente estável, rápido e previsível, tanto em retas quanto em curvas.`,
      design: `O design do Arteon Shooting Brake R é um dos seus maiores destaques. Ele combina a elegância de um cupê com a praticidade de uma perua, criando uma silhueta fluida e sofisticada. A dianteira é marcada por uma grade ampla integrada aos faróis em LED, criando uma identidade visual moderna e imponente.\n\nA versão R adiciona elementos esportivos como detalhes em preto brilhante, para-choques exclusivos, rodas de grande diâmetro e o clássico sistema de quatro saídas de escape, reforçando seu caráter de alto desempenho.`,
      luxury: `O interior do Arteon Shooting Brake R oferece um ambiente sofisticado e tecnológico, com materiais de alta qualidade como couro premium, alumínio escovado e acabamentos refinados. Os bancos esportivos proporcionam excelente conforto e suporte, sendo ideais tanto para uso diário quanto para condução mais agressiva.\n\nO espaço interno é amplo, especialmente no porta-malas, reforçando a proposta de versatilidade do modelo. Além disso, recursos como iluminação ambiente, sistema de som premium e conectividade avançada elevam a experiência a um nível superior.`,
    },

    "Porsche Carrera GT": {
      id: "25",
      fullDescription: `O Porsche Carrera GT é um dos supercarros mais puros e lendários já produzidos, representando uma era em que a conexão entre homem e máquina era direta, intensa e sem filtros eletrônicos excessivos. Desenvolvido com tecnologia derivada das pistas, o Carrera GT é um carro que exige respeito e habilidade, entregando uma experiência de condução visceral e extremamente envolvente. Ele não foi feito para facilitar — foi feito para recompensar quem sabe extrair o máximo de um verdadeiro carro de engenharia analógica.`,
      history: `O Carrera GT nasceu a partir de um projeto de corrida da Porsche no final dos anos 90. Inicialmente, a marca alemã desenvolvia um motor V10 para competições como as 24 Horas de Le Mans, mas mudanças nas regulamentações fizeram com que o projeto fosse adaptado para um carro de produção.\n\nO modelo foi apresentado como conceito em 2000, e devido à recepção extremamente positiva, a Porsche decidiu colocá-lo em produção limitada entre 2004 e 2007, com cerca de 1.270 unidades fabricadas.\n\nO Carrera GT rapidamente se tornou um dos carros mais icônicos da Porsche, não apenas por sua raridade, mas por sua proposta purista. Ele representa uma época anterior à dominância de sistemas eletrônicos avançados, onde o controle do carro dependia muito mais da habilidade do motorista.`,
      technology: `Apesar de sua proposta mais “analógica”, o Carrera GT incorpora tecnologias extremamente avançadas para sua época. Sua estrutura é baseada em um monocoque de fibra de carbono, garantindo alta rigidez e baixo peso — uma solução diretamente inspirada em carros de corrida.\n\nA suspensão utiliza um sistema sofisticado de braços duplos sobrepostos, proporcionando excelente controle em curvas. O carro também conta com freios cerâmicos (PCCB), que oferecem alta resistência ao calor e desempenho consistente em uso extremo.`,
      performance: `No coração do Porsche Carrera GT está um impressionante motor V10 naturalmente aspirado de 5.7 litros, capaz de produzir cerca de 612 cavalos de potência. Esse motor é derivado diretamente de um projeto de corrida, o que explica sua personalidade agressiva e sua capacidade de girar em altas rotações.\n\nO carro é capaz de acelerar de 0 a 100 km/h em aproximadamente 3,9 segundos e atingir velocidades superiores a 330 km/h. Mais do que os números, o que realmente define o Carrera GT é a forma como ele entrega sua performance: sem filtros, sem assistência excessiva e com uma resposta extremamente direta ao acelerador.`,
      design: `O design do Carrera GT é uma combinação de elegância e funcionalidade aerodinâmica. Suas linhas são limpas e atemporais, com proporções clássicas de supercarro: carroceria baixa, larga e com cabine avançada.\n\nUm dos elementos mais marcantes do design são os tubos de escape posicionados no topo da traseira, que não apenas criam uma assinatura visual única, mas também contribuem para a redução de calor na parte inferior do carro.\n\nA traseira aberta, com destaque para o motor e a suspensão, reforça a conexão do carro com o automobilismo. Cada detalhe do design foi pensado para equilibrar estética e desempenho, resultando em um visual que continua impressionante mesmo décadas após seu lançamento.`,
      luxury: `Embora o foco principal do Carrera GT seja performance, o interior oferece um nível de refinamento característico da Porsche. Materiais como couro de alta qualidade, fibra de carbono e alumínio são utilizados para criar um ambiente sofisticado, mas sem excessos.\n\nO destaque do interior é o icônico manopla de câmbio em madeira, uma homenagem aos carros de corrida clássicos da Porsche, que adiciona um toque artesanal e único ao cockpit.\n\nOs bancos esportivos oferecem bom suporte, enquanto o layout do painel é simples e funcional, mantendo o foco total na condução. Não há distrações desnecessárias, tudo existe para reforçar a conexão entre o motorista e o carro.`,
    },
    "Pagani Utopia": {
      id: "26",
      fullDescription: `O Pagani Utopia é a expressão mais pura da filosofia de Horacio Pagani: unir arte, engenharia e emoção em um automóvel. Mais do que um hipercarro, o Utopia é uma peça de design funcional, onde cada componente é tratado como uma obra artesanal. Em um mundo dominado por digitalização e eletrificação, o Utopia surge como uma declaração ousada, um carro que valoriza a conexão humana, a mecânica visível e a experiência sensorial acima de tudo. Ele não busca apenas ser rápido, mas atemporal, oferecendo uma condução que transcende números e se transforma em experiência.`,
      history: `Apresentado em 2022, o Pagani Utopia é o sucessor direto do Huayra, dando continuidade a uma linhagem que começou com o lendário Zonda. A Pagani, uma fabricante extremamente exclusiva fundada por Horacio Pagani, sempre teve como objetivo criar carros que vão além da engenharia tradicional, misturando influências da arte renascentista com tecnologia de ponta.\n\nO Utopia nasceu com uma proposta clara: simplificar sem perder desempenho. Após anos de evolução tecnológica nos hipercarros, Pagani decidiu seguir na direção oposta de muitas tendências modernas, eliminando complexidades desnecessárias e resgatando a essência da condução.`,
      technology: `Embora sua proposta seja mais purista, o Pagani Utopia incorpora tecnologias extremamente avançadas. Sua estrutura utiliza um composto exclusivo chamado Carbo-Titanium, uma mistura de fibra de carbono com titânio que oferece rigidez estrutural excepcional com peso reduzido.\n\nO motor, desenvolvido pela Mercedes-AMG, é um V12 biturbo de 6.0 litros, projetado para entregar potência de forma linear e previsível. Diferente de muitos hipercarros modernos, o Utopia oferece a opção de transmissão manual, algo extremamente raro nesse segmento, além de uma caixa automatizada para quem busca maior praticidade.`,
      performance: `O Pagani Utopia entrega aproximadamente 864 cavalos de potência e cerca de 1.100 Nm de torque, números impressionantes que garantem acelerações extremamente rápidas e uma performance digna dos melhores hipercarros do mundo.\n\nNo entanto, o foco do Utopia não está apenas na velocidade máxima ou no tempo de 0 a 100 km/h, mas na qualidade da entrega de potência. O motor V12 biturbo oferece resposta progressiva e controle refinado, permitindo que o motorista explore o carro com confiança.\n\nA combinação entre peso reduzido, chassi avançado e engenharia precisa resulta em um carro extremamente equilibrado, que privilegia a sensação de controle e a conexão direta com a máquina.`,
      design: `O design do Pagani Utopia é uma evolução refinada da linguagem estética da marca. Ele mantém elementos clássicos vistos no Zonda e no Huayra, mas com linhas mais limpas e proporções ainda mais equilibradas.\n\nCada detalhe da carroceria tem uma função, seja aerodinâmica ou estrutural. As superfícies são esculpidas de forma orgânica, criando um fluxo visual contínuo que mistura elegância e agressividade. Elementos como os quatro escapamentos centrais, assinatura da Pagani, reforçam a identidade única do carro.\n\nAs portas em estilo asa de gaivota e o uso extensivo de fibra de carbono exposta contribuem para um visual que é ao mesmo tempo futurista e clássico, mantendo o carro relevante por décadas.`,
      luxury: `O interior do Pagani Utopia é onde a filosofia da marca se manifesta de forma mais clara. Em vez de telas digitais dominantes, o cockpit é preenchido por componentes mecânicos expostos, mostradores analógicos e detalhes usinados com precisão absoluta.\n\nMateriais como couro premium, alumínio fresado, fibra de carbono e titânio são combinados de forma artesanal, criando um ambiente que se assemelha mais a um relógio de alta relojoaria do que a um carro convencional.\n\nCada botão, cada engrenagem e cada acabamento são projetados para oferecer não apenas funcionalidade, mas também prazer visual e tátil. O nível de personalização é extremo, permitindo que cada unidade seja única.`,
    },
    "Maserati GT2 Stradale": {
      id: "27",
      fullDescription: `O Maserati GT2 Stradale é a tradução direta de um carro de corrida para as ruas, representando o retorno da Maserati ao universo das competições com uma proposta extremamente focada em desempenho. Inspirado no GT2 de pista, o modelo Stradale nasce com o objetivo de entregar uma experiência visceral, onde cada detalhe é pensado para maximizar eficiência, controle e conexão com o motorista. Ele combina a elegância tradicional da Maserati com uma abordagem muito mais agressiva e técnica, criando um supercarro que une emoção e precisão em níveis elevados.`,
      history: `O GT2 Stradale surge como consequência direta do retorno da Maserati às competições da categoria GT2, marcando um momento importante na história recente da marca italiana. Após anos focada em luxo e grand tourers, a Maserati decidiu resgatar seu DNA esportivo mais puro, utilizando o MC20 como base para desenvolver um carro de corrida altamente competitivo.\n\nA partir desse projeto de pista, nasceu a versão Stradale, uma adaptação homologada para as ruas, mantendo o máximo possível da essência do carro de competição. Esse movimento reforça a tradição da Maserati de transferir tecnologia das pistas para seus modelos de produção, algo que sempre fez parte da identidade da marca.`,
      technology: `O Maserati GT2 Stradale incorpora tecnologias diretamente derivadas do automobilismo. Sua estrutura utiliza um monocoque de fibra de carbono, garantindo alta rigidez e baixo peso, elementos essenciais para desempenho em pista.\n\nA aerodinâmica é um dos pilares do carro, com um pacote extremamente avançado que inclui aerofólio traseiro fixo, difusor de grandes dimensões e entradas de ar otimizadas, todos projetados para gerar alto nível de downforce e melhorar a estabilidade em altas velocidades.`,
      performance: `No coração do GT2 Stradale está o motor Nettuno V6 biturbo de 3.0 litros, uma das maiores inovações recentes da Maserati. Esse motor utiliza tecnologia inspirada na Fórmula 1, como o sistema de combustão com pré-câmara, permitindo maior eficiência e desempenho.\n\nA potência gira em torno de 640 cavalos, garantindo acelerações extremamente rápidas e uma entrega de potência agressiva. O carro é capaz de acelerar de 0 a 100 km/h em cerca de 2,8 segundos, com velocidade máxima superior a 320 km/h.`,
      design: `O design do Maserati GT2 Stradale é fortemente influenciado pelo carro de corrida do qual deriva. Cada elemento visual tem uma função aerodinâmica clara, resultando em uma estética agressiva e altamente técnica.\n\nA dianteira apresenta entradas de ar amplas e um splitter pronunciado, enquanto a traseira é dominada por um grande aerofólio e um difusor funcional. As linhas da carroceria são esculpidas para otimizar o fluxo de ar, criando um visual que transmite velocidade e precisão.`,
      luxury: `Mesmo sendo um carro extremamente focado em pista, o GT2 Stradale não abandona completamente o luxo. O interior combina materiais como Alcantara, fibra de carbono e couro premium, criando um ambiente esportivo, mas ainda refinado.\n\nO cockpit é orientado ao motorista, com comandos posicionados de forma ergonômica para facilitar o uso durante condução intensa. Os bancos são leves e oferecem excelente suporte lateral, reforçando a proposta de performance.`,
    },
    "Lotus Emira V6 SE": {
      id: "28",
      fullDescription: `O Lotus Emira V6 SE representa uma nova era para a Lotus, sendo o último modelo da marca equipado exclusivamente com motor a combustão antes da transição para a eletrificação. Ele combina o DNA tradicional da Lotus, leveza, precisão e foco na dirigibilidade com um nível de refinamento e usabilidade que nunca foi tão presente na história da fabricante britânica. O Emira não é apenas um esportivo, mas uma evolução do conceito Lotus, trazendo mais conforto, tecnologia e acabamento sem perder a essência purista que consagrou a marca.`,
      history: `Apresentado em 2021, o Emira substitui modelos como Elise, Exige e Evora, consolidando em um único carro décadas de aprendizado da Lotus. Ele marca um momento importante de transformação da empresa, que passou a fazer parte do grupo Geely e iniciou uma nova fase de expansão global.\n\nA versão V6 SE carrega um significado especial dentro dessa transição. Ela mantém viva a tradição dos motores supercharged e da condução analógica, ao mesmo tempo em que incorpora melhorias significativas em ergonomia, qualidade de construção e tecnologia. O Emira é, portanto, um elo entre o passado e o futuro da Lotus.`,
      technology: `O Lotus Emira V6 SE combina engenharia clássica com tecnologias modernas. Sua estrutura utiliza um chassi de alumínio colado, técnica tradicional da Lotus, que garante excelente rigidez com baixo peso. A suspensão foi cuidadosamente calibrada para oferecer equilíbrio ideal entre conforto e performance, com opções de ajuste que atendem tanto ao uso diário quanto à condução esportiva.\n\nO carro também conta com direção hidráulica — algo cada vez mais raro — que proporciona feedback extremamente preciso ao motorista. Sistemas eletrônicos como controle de tração ajustável e modos de condução ajudam a adaptar o comportamento do carro sem interferir excessivamente na experiência de dirigir.`,
      performance: `O coração do Emira V6 SE é um motor V6 de 3.5 litros supercharged, fornecido pela Toyota e amplamente refinado pela Lotus. Esse motor entrega aproximadamente 400 cavalos de potência, oferecendo uma resposta imediata ao acelerador e uma experiência de condução envolvente.\n\nO carro pode acelerar de 0 a 100 km/h em cerca de 4,3 segundos, com velocidade máxima próxima de 290 km/h. A transmissão pode ser manual ou automática, sendo a versão manual especialmente valorizada por entusiastas que buscam uma conexão mais direta com o carro.`,
      design: `O design do Lotus Emira é uma evolução significativa em relação aos modelos anteriores da marca. Ele adota linhas mais modernas e sofisticadas, com forte influência do hipercarro elétrico Evija.\n\nA carroceria apresenta entradas de ar esculpidas de forma orgânica, que não apenas contribuem para a estética, mas também desempenham papel fundamental na aerodinâmica e no resfriamento do motor. A silhueta baixa e larga reforça o caráter esportivo do carro, enquanto os detalhes em LED e os acabamentos refinados elevam a percepção de qualidade.`,
      luxury: `O interior do Lotus Emira V6 SE representa um salto significativo em termos de qualidade e conforto para a marca. Materiais como couro, Alcantara, alumínio e acabamentos de alta qualidade criam um ambiente sofisticado, algo que historicamente não era o foco principal da Lotus.\n\nOs bancos oferecem bom suporte para condução esportiva, mas também são confortáveis para uso diário. O sistema multimídia moderno, o painel digital e os recursos de conectividade tornam o carro mais prático e alinhado com as expectativas atuais.`,
    },
    "Alfa Romeo Giulia Quadrifoglio Estrema": {
      id: "29",
      fullDescription: `O Alfa Romeo Giulia Quadrifoglio Estrema é uma das expressões mais intensas da tradição esportiva italiana aplicada a um sedã. Ele combina elegância, emoção e desempenho de forma única, trazendo uma experiência de condução visceral que poucos carros da categoria conseguem oferecer. A versão Estrema eleva ainda mais o já impressionante Giulia Quadrifoglio, incorporando elementos adicionais de leveza, aerodinâmica e refinamento dinâmico, posicionando-se como uma versão ainda mais focada para entusiastas.`,
      history: `O Giulia Quadrifoglio representa o renascimento da Alfa Romeo no segmento de alta performance, sendo lançado como um rival direto dos principais sedãs esportivos alemães. O nome Quadrifoglio — o famoso trevo de quatro folhas — carrega décadas de história nas pistas, simbolizando sorte e desempenho desde as competições da marca no início do século XX.\n\nA versão Estrema surge como uma evolução dentro dessa linhagem, trazendo melhorias inspiradas em modelos ainda mais extremos, como o Giulia GTA. Ela reforça o compromisso da Alfa Romeo em manter viva sua herança esportiva, oferecendo um carro que não apenas compete em números, mas também em emoção e personalidade.`,
      technology: `O Giulia Quadrifoglio Estrema incorpora tecnologias avançadas focadas em desempenho e controle. Um dos principais destaques é o uso extensivo de fibra de carbono, presente em componentes como o capô, teto e elementos aerodinâmicos, contribuindo para redução de peso e melhor dinâmica.\n\nO carro conta com suspensão ativa, diferencial traseiro eletrônico e diversos modos de condução através do sistema DNA Pro, que permite ajustar o comportamento do veículo conforme a preferência do motorista — desde conforto até um modo focado totalmente em pista.\n\nAlém disso, sistemas eletrônicos avançados garantem estabilidade, tração e controle, enquanto o interior recebe atualizações tecnológicas com painel digital e sistema multimídia moderno.`,
      performance: `Sob o capô, o Giulia Quadrifoglio Estrema abriga um poderoso motor V6 biturbo de 2.9 litros, desenvolvido com influência direta da Ferrari. Esse motor entrega cerca de 510 cavalos de potência, proporcionando acelerações extremamente rápidas.\n\nO carro é capaz de acelerar de 0 a 100 km/h em aproximadamente 3,9 segundos, com velocidade máxima superior a 300 km/h. A tração traseira, combinada com o diferencial ativo e o acerto refinado do chassi, oferece uma condução extremamente dinâmica e envolvente.`,
      design: `O design do Giulia Quadrifoglio Estrema mantém a elegância italiana característica da Alfa Romeo, mas com um toque mais agressivo e técnico. A dianteira apresenta a tradicional grade Scudetto, acompanhada por entradas de ar ampliadas e elementos aerodinâmicos em fibra de carbono.\n\nAs linhas da carroceria são fluidas e bem proporcionadas, criando um visual sofisticado que esconde sua verdadeira capacidade de desempenho. A versão Estrema adiciona detalhes exclusivos que reforçam sua identidade, como acabamentos escurecidos e componentes mais esportivos.`,
      luxury: `O interior do Giulia Quadrifoglio Estrema combina esportividade com sofisticação. Materiais como Alcantara, couro premium e fibra de carbono criam um ambiente refinado, mas claramente voltado para o desempenho.\n\nOs bancos esportivos oferecem excelente suporte lateral, ideais para condução agressiva, ao mesmo tempo em que mantêm conforto para uso diário. O acabamento é cuidadosamente trabalhado, refletindo o cuidado italiano com design e detalhes.\n\nO sistema de infotainment, o painel digital e os recursos de conectividade garantem uma experiência moderna, enquanto o ambiente geral mantém o foco na condução.`,
    },
    "Cadillac CT5-V Blackwing F1 Collector Series": {
      id: "30",
      fullDescription: `O Cadillac CT5-V Blackwing F1 Collector Series é uma edição especial que celebra a entrada da Cadillac no universo da Fórmula 1, combinando o caráter brutal de um dos sedãs mais potentes do mundo com elementos exclusivos inspirados no automobilismo de elite. Baseado no já impressionante CT5-V Blackwing, essa versão vai além da performance pura, trazendo identidade, exclusividade e um forte vínculo com a engenharia de competição. É um carro que mistura luxo americano, potência extrema e um toque de história sendo escrita dentro das pistas mais prestigiadas do planeta.`,
      history: `O CT5-V Blackwing já nasceu como o ápice da divisão de performance da Cadillac, sendo um dos últimos grandes sedãs esportivos equipados com motor V8 supercharged e câmbio manual disponíveis no mercado. A edição F1 Collector Series surge como uma homenagem à nova fase da marca, marcada pela sua entrada na Fórmula 1, reforçando a ambição da Cadillac de competir no mais alto nível do automobilismo mundial.\n\nEssa edição especial carrega detalhes exclusivos que fazem referência ao universo da F1, transformando o carro em uma peça de coleção. Mais do que uma simples variação estética, ela simboliza a conexão entre o desenvolvimento de carros de rua e a tecnologia de ponta aplicada nas pistas.`,
      technology: `O Cadillac CT5-V Blackwing F1 Collector Series incorpora tecnologias avançadas voltadas para desempenho e controle. Um dos destaques é o sistema Magnetic Ride Control 4.0, que utiliza amortecedores magnetorreológicos capazes de ajustar a rigidez da suspensão em tempo real, oferecendo um equilíbrio excepcional entre conforto e performance.\n\nO carro também conta com o Performance Traction Management (PTM), sistema que integra controle de tração, estabilidade e gerenciamento de potência, permitindo diferentes níveis de intervenção para adaptação ao estilo de condução do motorista.\n\nFreios de alta performance, opções em carbono-cerâmica, e um conjunto estrutural altamente rígido garantem controle absoluto mesmo em condições extremas.`,
      performance: `Sob o capô, o CT5-V Blackwing abriga um monstruoso motor V8 supercharged de 6.2 litros, capaz de entregar cerca de 668 cavalos de potência e aproximadamente 893 Nm de torque. Esses números colocam o carro entre os sedãs mais potentes já produzidos.\n\nEle é capaz de acelerar de 0 a 100 km/h em cerca de 3,4 segundos, com velocidade máxima superior a 320 km/h. A presença de uma transmissão manual de seis marchas (ou automática opcional) reforça a proposta purista do carro, oferecendo uma conexão direta entre motorista e máquina.`,
      design: `O design do CT5-V Blackwing F1 Collector Series mantém a base agressiva do modelo original, mas adiciona elementos exclusivos que reforçam sua identidade especial. A carroceria apresenta linhas musculosas, com uma postura imponente e detalhes aerodinâmicos funcionais.\n\nElementos em fibra de carbono, entradas de ar ampliadas, difusor traseiro e o conjunto de quatro saídas de escape reforçam o caráter esportivo do carro. A edição F1 adiciona detalhes visuais únicos, como acabamentos especiais, emblemas exclusivos e possíveis referências às cores e identidade da equipe.`,
      luxury: `O interior do Cadillac CT5-V Blackwing F1 Collector Series combina luxo americano com um toque esportivo sofisticado. Materiais como couro premium, fibra de carbono, Alcantara e acabamentos metálicos criam um ambiente refinado e exclusivo.\n\nOs bancos esportivos oferecem excelente suporte lateral, ideais para condução agressiva, mas também garantem conforto para uso cotidiano. O sistema de som premium, iluminação ambiente e recursos avançados de conectividade elevam a experiência a um nível superior.`,
    },
    "Gordon Murray Automotive T.33": {
      id: "31",
      fullDescription: `O Gordon Murray Automotive T.33 é a materialização de uma filosofia rara no mundo automotivo moderno: a busca pela pureza absoluta na experiência de dirigir. Criado por Gordon Murray, o lendário engenheiro por trás de ícones como o McLaren F1, o T.33 foi concebido como um supercarro analógico, focado em leveza, simplicidade mecânica e conexão direta entre motorista e máquina. Em vez de competir por números extremos de potência ou tecnologias excessivamente complexas, o T.33 aposta em equilíbrio, resposta imediata e prazer ao volante — uma abordagem que o torna único em sua categoria.`,
      history: `Apresentado em 2022, o T.33 surge como o segundo modelo da Gordon Murray Automotive, seguindo o radical T.50. Enquanto o T.50 foi projetado como um carro extremo, praticamente um Fórmula 1 para as ruas, o T.33 foi desenvolvido com uma proposta mais utilizável no dia a dia, sem abrir mão da essência purista da marca.\n\nGordon Murray utilizou décadas de experiência no automobilismo e na engenharia de supercarros para criar um veículo que resgata valores clássicos, muitas vezes esquecidos na indústria atual. O T.33 é, portanto, uma resposta direta à tendência de eletrificação e digitalização excessiva, mantendo vivo o espírito dos esportivos analógicos.`,
      technology: `Apesar de sua proposta minimalista, o T.33 incorpora soluções altamente sofisticadas. Sua estrutura é baseada em um monocoque de fibra de carbono ultraleve, garantindo rigidez estrutural excepcional com peso reduzido.\n\nA suspensão foi projetada para oferecer conforto e controle, utilizando componentes leves e geometria refinada para maximizar a estabilidade e a precisão em curvas. Diferente de muitos supercarros modernos, o T.33 evita sistemas eletrônicos intrusivos, priorizando uma experiência mais pura e previsível.\n\nO carro oferece a opção de transmissão manual de seis marchas, além de uma automática, reforçando o compromisso com a condução tradicional. A direção hidráulica proporciona feedback direto, algo cada vez mais raro nos carros atuais.`,
      performance: `No coração do T.33 está um extraordinário motor V12 naturalmente aspirado de 3.9 litros, desenvolvido pela Cosworth. Esse motor entrega aproximadamente 615 cavalos de potência e é capaz de atingir rotações extremamente altas, proporcionando uma experiência sonora e mecânica incomparável.\n\nEmbora os números de aceleração sejam impressionantes, o foco do T.33 está na forma como o desempenho é entregue. A resposta do acelerador é imediata, e a ausência de turbocompressores garante uma conexão direta entre o motorista e o motor.`,
      design: `O design do Gordon Murray T.33 segue uma abordagem mais limpa e atemporal, em contraste com a estética agressiva de muitos supercarros modernos. Suas linhas são suaves e elegantes, com proporções clássicas que remetem a esportivos icônicos do passado.\n\nCada elemento do carro foi projetado com foco na funcionalidade, sem exageros aerodinâmicos. A traseira apresenta soluções inteligentes para gerenciamento de fluxo de ar, enquanto a carroceria em fibra de carbono contribui para a leveza e eficiência.`,
      luxury: `O interior do T.33 reflete a mesma filosofia de simplicidade sofisticada. Em vez de telas grandes e sistemas digitais complexos, o cockpit apresenta instrumentos analógicos, controles físicos e um design focado no motorista.\n\nMateriais de alta qualidade como couro premium, alumínio usinado e fibra de carbono são utilizados de forma elegante e discreta. Cada detalhe é cuidadosamente trabalhado para oferecer uma experiência tátil e visual refinada.\n\nOs bancos são projetados para conforto em longas viagens, reforçando a proposta do carro como um grand tourer esportivo. O resultado é um ambiente que combina luxo com funcionalidade, onde o foco principal continua sendo a condução.`,
    },
    "Honda Civic Type R Ultimate Edition": {
      id: "32",
      fullDescription: `O Honda Civic Type R Ultimate Edition representa o ápice de um dos hot hatches mais respeitados da história. Ele combina a tradição da Honda em engenharia de precisão com uma abordagem focada em desempenho extremo, oferecendo uma experiência de condução envolvente, direta e altamente refinada. Essa edição especial leva o já impressionante Civic Type R a um novo nível, incorporando elementos exclusivos que destacam seu caráter de despedida ou celebração dentro da linhagem Type R. É um carro que equilibra perfeitamente usabilidade diária com capacidade real de pista.`,
      history: `A linhagem Type R começou nos anos 90 com modelos focados em extrair o máximo desempenho de carros de produção, sempre com ênfase em leveza, resposta e comportamento dinâmico. O Civic Type R rapidamente se tornou o principal representante dessa filosofia, evoluindo ao longo das gerações como um dos melhores carros de tração dianteira do mundo.\n\nA Ultimate Edition surge como uma versão especial que celebra essa trajetória, trazendo detalhes exclusivos e possivelmente marcando o fim de uma era antes de mudanças importantes na linha, como eletrificação ou novas abordagens de engenharia. Assim como outras edições limitadas da Honda, ela carrega um forte apelo emocional e colecionável.`,
      technology: `O Civic Type R Ultimate Edition incorpora tecnologias avançadas voltadas para maximizar desempenho e controle. O carro utiliza uma plataforma altamente rígida, com suspensão independente refinada e ajustes específicos para uso esportivo intenso.\n\nO sistema de condução inclui modos ajustáveis que alteram parâmetros como resposta do acelerador, direção, suspensão e controle de tração. O diferencial LSD (Limited Slip Differential) é fundamental para garantir tração eficiente, especialmente em curvas, minimizando perda de aderência típica de carros de tração dianteira.\n\nO interior conta com um painel digital moderno e sistema multimídia atualizado, além de recursos como telemetria em tempo real, permitindo ao motorista acompanhar dados de desempenho durante a condução esportiva.`,
      performance: `Sob o capô, o Civic Type R Ultimate Edition mantém o consagrado motor 2.0 turbo VTEC, capaz de entregar aproximadamente 330 cavalos de potência. Esse conjunto, aliado a uma transmissão manual de seis marchas, proporciona uma experiência extremamente envolvente e rara nos dias atuais.\n\nO carro acelera de 0 a 100 km/h em cerca de 5,4 segundos, com foco não apenas em velocidade, mas principalmente em eficiência em curvas. A tração dianteira, combinada com o diferencial LSD e o acerto refinado do chassi, permite níveis impressionantes de aderência e controle.\n\nO resultado é um dos carros mais rápidos em circuitos para sua categoria, frequentemente estabelecendo recordes em pistas ao redor do mundo para veículos de tração dianteira.`,
      design: `O design do Civic Type R Ultimate Edition é agressivo e funcional, refletindo claramente sua proposta esportiva. A carroceria apresenta linhas marcantes, com entradas de ar amplas, para-lamas alargados e elementos aerodinâmicos que contribuem para o desempenho.\n\nA traseira é dominada pelo icônico aerofólio grande e o sistema de três saídas de escape, que não apenas definem a estética do carro, mas também ajudam na eficiência aerodinâmica e no som característico.\n\nA edição Ultimate adiciona detalhes exclusivos, como acabamentos especiais, possíveis cores diferenciadas e elementos que reforçam sua identidade única dentro da linha Type R.`,
      luxury: `Embora o foco principal seja desempenho, o Civic Type R Ultimate Edition oferece um interior bem equipado e refinado dentro de sua proposta. Materiais como Alcantara, tecido esportivo e acabamentos de qualidade criam um ambiente funcional e esportivo.\n\nOs bancos esportivos, tradicionalmente em vermelho, oferecem excelente suporte lateral, garantindo estabilidade durante condução agressiva. O espaço interno e a praticidade do hatchback tornam o carro utilizável no dia a dia, algo que poucos esportivos conseguem oferecer com esse nível de performance.`,
    },
    "Mazda RX-7 Fortune by VeilSide": {
      id: "33",
      fullDescription: `O Mazda RX-7 Fortune by VeilSide é uma das customizações mais icônicas da cultura automotiva japonesa, elevando o já lendário RX-7 FD a um nível completamente novo de presença visual e exclusividade. Criado pela preparadora japonesa VeilSide, o modelo “Fortune” transforma o esportivo em uma verdadeira obra de arte sobre rodas, com um design extremamente agressivo e único. Mais do que um carro modificado, ele se tornou um símbolo global do tuning e da cultura JDM, especialmente após sua aparição marcante no cinema.`,
      history: `O Mazda RX-7 FD3S já era um ícone por si só, graças ao seu design elegante e ao lendário motor rotativo. No entanto, foi com o kit Fortune da VeilSide que o carro ganhou uma nova identidade, chamando atenção mundial.\n\nEssa versão ficou eternizada no filme “The Fast and the Furious: Tokyo Drift”, onde foi pilotada pelo personagem Han, interpretado por Sung Kang. O carro, com sua pintura laranja vibrante e carroceria extremamente larga, rapidamente se tornou um dos veículos mais memoráveis da franquia.\n\nO kit Fortune não é apenas estético — ele envolve uma transformação profunda da carroceria, com grande parte dos painéis sendo substituída. Isso faz com que o carro seja praticamente único, elevando seu status entre colecionadores e entusiastas.`,
      technology: `Embora o foco principal do VeilSide Fortune seja o design, ele mantém a base tecnológica do RX-7 FD, que já era avançada para sua época. O carro utiliza um chassi leve e bem equilibrado, com suspensão independente nas quatro rodas, proporcionando excelente comportamento dinâmico.\n\nO motor continua sendo o famoso 13B-REW, um rotativo biturbo de 1.3 litros, conhecido por sua capacidade de gerar alta potência com baixo peso. Muitos modelos Fortune recebem modificações adicionais no motor, incluindo upgrades de turbo, intercooler e sistema de escape, elevando significativamente o desempenho.\n\nA combinação entre leveza, tração traseira e equilíbrio torna o carro extremamente ágil, mantendo a essência esportiva do RX-7 original.`,
      performance: `Em sua configuração original, o RX-7 FD entrega cerca de 280 cavalos de potência, mas versões modificadas — como muitas unidades com kit VeilSide — frequentemente ultrapassam esse número com facilidade.\n\nO carro pode acelerar de 0 a 100 km/h em cerca de 5 segundos, dependendo da preparação. O grande diferencial está na forma como a potência é entregue, com o motor rotativo oferecendo uma experiência única, com rotações elevadas e som característico.\n\nApesar do foco visual do kit Fortune, o RX-7 continua sendo um carro extremamente capaz, especialmente em curvas, graças ao seu baixo peso e excelente distribuição de massa.`,
      design: `O design é, sem dúvida, o ponto mais marcante do Mazda RX-7 Fortune by VeilSide. O kit altera drasticamente a aparência do carro, com para-lamas extremamente alargados, para-choques redesenhados, capô exclusivo e uma traseira completamente reformulada.\n\nA largura do carro aumenta significativamente, criando uma presença visual agressiva e imponente. As linhas originais do RX-7 são reinterpretadas de forma mais exagerada e futurista, resultando em um visual que divide opiniões, mas que é inegavelmente icônico.\n\nA pintura laranja associada ao modelo de “Tokyo Drift” se tornou uma assinatura visual, reforçando ainda mais sua identidade única.`,
      luxury: `O interior do RX-7 Fortune segue uma proposta mais simples e focada na condução, mas pode variar bastante dependendo da personalização de cada unidade. Muitos modelos recebem bancos esportivos, volantes aftermarket e acabamentos personalizados.\n\nEmbora não seja um carro luxuoso no sentido tradicional, ele oferece um tipo diferente de exclusividade: a sensação de dirigir algo verdadeiramente único e carregado de história.`,
    },
    "Mitsubishi Lancer Evolutin X Carbon Series": {
      id: "34",
      fullDescription: `O Mitsubishi Lancer Evolution X Carbon Series é uma das versões mais especiais e desejadas do lendário Evo X, elevando ainda mais o caráter agressivo e técnico do modelo com foco em leveza, estética e exclusividade. Ele representa o ápice de uma linhagem que sempre foi sinônimo de performance acessível, tração integral avançada e domínio em qualquer tipo de terreno. A Carbon Series adiciona um toque mais refinado e esportivo, destacando-se pelo uso de materiais leves e detalhes únicos que reforçam sua identidade dentro da família Evolution.`,
      history: `O Lancer Evolution X, lançado em 2007, marcou a última geração da icônica linha Evolution, encerrando uma história que começou nos anos 90 com forte ligação ao automobilismo, especialmente ao rally mundial. Ao longo das gerações, o Evo construiu uma reputação sólida como um dos carros mais eficazes e precisos em termos de desempenho.\n\nA versão Carbon Series surge como uma edição especial dentro dessa última geração, destacando-se por elementos exclusivos em fibra de carbono e acabamento diferenciado. Ela representa uma espécie de despedida refinada da linhagem Evolution, que foi descontinuada pouco tempo depois, tornando essas versões ainda mais valorizadas entre colecionadores e entusiastas.`,
      technology: `O Lancer Evolution X Carbon Series incorpora um conjunto tecnológico altamente focado em desempenho. Um dos principais destaques é o sistema de tração integral Super All-Wheel Control (S-AWC), que integra diferentes sistemas eletrônicos para distribuir torque de forma inteligente entre as rodas, garantindo máxima aderência e controle.\n\nO carro também conta com diferenciais ativos, controle de estabilidade avançado e modos de condução que permitem ajustar o comportamento do veículo conforme o tipo de terreno ou estilo de direção. A suspensão independente e o chassi altamente rígido contribuem para uma resposta rápida e previsível.\n\nA edição Carbon adiciona elementos estruturais e visuais em fibra de carbono, como capô e outros detalhes, ajudando a reduzir peso e melhorar o desempenho geral.`,
      performance: `Sob o capô, o Evolution X Carbon Series mantém o robusto motor 4B11T, um 2.0 turbo de quatro cilindros, capaz de entregar cerca de 295 cavalos de potência e aproximadamente 366 Nm de torque.\n\nO carro pode acelerar de 0 a 100 km/h em torno de 5 segundos, com excelente tração graças ao sistema S-AWC. A transmissão pode variar entre manual de cinco marchas ou a automática de dupla embreagem SST, dependendo da configuração.\n\nO grande diferencial do Evo X está na sua capacidade em curvas e superfícies desafiadoras. Ele oferece um nível de controle impressionante, sendo extremamente eficiente tanto em asfalto quanto em condições de baixa aderência.`,
      design: `O design do Lancer Evolution X Carbon Series é agressivo e funcional, refletindo claramente sua origem no rally. A dianteira é marcada pela icônica grade frontal ampla, conhecida como “Jet Fighter”, acompanhada por entradas de ar que auxiliam no resfriamento do motor.\n\nA versão Carbon se destaca por detalhes em fibra de carbono, que adicionam um visual mais técnico e esportivo ao carro. O grande aerofólio traseiro, as linhas angulares e os para-lamas pronunciados reforçam sua presença imponente.`,
      luxury: `O interior do Evolution X Carbon Series mantém um equilíbrio entre esportividade e funcionalidade. Materiais como Alcantara, couro e detalhes em fibra de carbono criam um ambiente mais refinado em comparação com versões mais básicas.\n\nOs bancos esportivos Recaro oferecem excelente suporte lateral, ideais para condução agressiva, enquanto o layout do painel é focado no motorista, garantindo fácil acesso aos controles.\n\nEmbora não seja um carro voltado ao luxo tradicional, ele entrega conforto suficiente para o uso diário, combinado com uma experiência de condução envolvente. O verdadeiro diferencial está na sensação de controle e na conexão com o carro, características que fizeram do Evolution uma lenda.`,
    },
    "Nissan 370Z S-Tune by Nismo": {
      id: "35",
      fullDescription: `O Nissan 370Z S-Tune by NISMO é uma interpretação mais refinada e equilibrada do clássico esportivo japonês, combinando o DNA puro da linha Z com o know-how da divisão de performance da Nissan. Diferente de versões mais extremas, o pacote S-Tune foi desenvolvido para melhorar a experiência de condução sem comprometer o conforto e a usabilidade no dia a dia. O resultado é um carro que mantém a essência esportiva do 370Z, mas com um comportamento mais preciso, estável e envolvente.`,
      history: `A linha NISMO (Nissan Motorsports) sempre teve um papel fundamental no desenvolvimento de versões mais esportivas e focadas em performance dos modelos da marca. O pacote S-Tune segue essa filosofia, sendo projetado como um upgrade oficial que equilibra desempenho e dirigibilidade.\n\nO Nissan 370Z, sucessor do 350Z, foi lançado em 2009 como parte da icônica família Z, uma linhagem que começou ainda nos anos 60 e se tornou uma das mais respeitadas no mundo dos esportivos. A versão S-Tune surge como uma opção para entusiastas que desejam melhorar o comportamento dinâmico do carro sem recorrer a modificações extremas.`,
      technology: `O 370Z S-Tune by NISMO mantém a base tecnológica sólida do modelo original, com foco em aprimoramentos mecânicos e dinâmicos. O pacote inclui ajustes específicos de suspensão, com molas e amortecedores recalibrados para oferecer melhor controle em curvas e maior estabilidade em altas velocidades.\n\nO carro também pode contar com melhorias no sistema de escape, aumentando a eficiência e proporcionando um som mais esportivo. A estrutura do chassi, já conhecida por sua rigidez, trabalha em conjunto com a suspensão ajustada para garantir uma condução mais precisa.`,
      performance: `Sob o capô, o 370Z S-Tune mantém o consagrado motor V6 VQ37VHR de 3.7 litros naturalmente aspirado, capaz de produzir cerca de 328 cavalos de potência e aproximadamente 366 Nm de torque.\n\nO carro acelera de 0 a 100 km/h em torno de 5,3 segundos, oferecendo uma entrega de potência linear e responsiva, característica dos motores aspirados. A transmissão pode ser manual de seis marchas ou automática, com foco em proporcionar uma experiência envolvente ao motorista.\n\nO diferencial do S-Tune está no comportamento dinâmico: a suspensão aprimorada e o ajuste fino do conjunto tornam o carro mais estável e previsível, elevando a confiança do motorista em condução esportiva.`,
      design: `O design do 370Z S-Tune by NISMO recebe melhorias sutis, mas eficazes. O pacote inclui elementos aerodinâmicos como saias laterais, para-choques revisados e detalhes exclusivos que reforçam o visual esportivo sem exageros.\n\nAs linhas do 370Z, já marcantes por natureza, permanecem praticamente inalteradas, mantendo o perfil clássico de um cupê esportivo com capô longo e traseira curta. Os detalhes adicionados pela NISMO trazem um toque mais agressivo e técnico, sem comprometer a elegância do conjunto.`,
      luxury: `O interior do 370Z S-Tune segue uma proposta focada no motorista, com acabamento esportivo e funcional. Materiais como couro, alumínio e detalhes exclusivos NISMO criam um ambiente agradável e alinhado com a proposta do carro.\n\nOs bancos esportivos oferecem bom suporte lateral, enquanto o layout do cockpit mantém tudo ao alcance do motorista, reforçando a sensação de controle. Embora não seja um carro focado em luxo extremo, ele oferece conforto suficiente para uso diário.`,
    },
    "Acura NSX Type S": {
      id: "36",
      fullDescription: `O Acura NSX Type S representa o ápice da segunda geração do lendário NSX, combinando tecnologia híbrida avançada, desempenho de supercarro e a filosofia japonesa de precisão mecânica. Desenvolvido como uma edição especial de despedida, o Type S refina todos os aspectos do NSX original, oferecendo mais potência, respostas mais agressivas e um comportamento dinâmico ainda mais afiado. É um carro que une inovação tecnológica e emoção ao volante de uma forma extremamente sofisticada, mantendo viva a tradição de um dos nomes mais respeitados da história automotiva japonesa.`,
      history: `O nome NSX carrega enorme importância dentro da indústria automotiva. A primeira geração, lançada nos anos 90, revolucionou o segmento de supercarros ao provar que um carro de alto desempenho poderia ser confiável, confortável e utilizável no dia a dia. Desenvolvido com participação direta de Ayrton Senna, o NSX original se tornou um ícone instantâneo.\n\nDécadas depois, a Acura trouxe o modelo de volta em uma proposta completamente moderna, utilizando tecnologia híbrida e foco em eficiência dinâmica. O NSX Type S, lançado em 2021, marcou o encerramento dessa segunda geração, sendo produzido em números extremamente limitados. Essa versão foi criada para representar a forma mais refinada e agressiva do NSX moderno, consolidando-se rapidamente como uma peça de coleção.`,
      technology: `O Acura NSX Type S é um dos supercarros tecnologicamente mais sofisticados de sua geração. Seu sistema híbrido combina um motor V6 biturbo com três motores elétricos, formando o avançado sistema Sport Hybrid SH-AWD.\n\nDois motores elétricos atuam no eixo dianteiro, permitindo controle vetorial de torque extremamente preciso, enquanto outro motor auxilia o conjunto traseiro. Essa configuração melhora aceleração, estabilidade e comportamento em curvas, criando uma experiência de condução extremamente eficiente e previsível.`,
      performance: `No coração do NSX Type S está um motor V6 biturbo de 3.5 litros, combinado ao sistema híbrido elétrico, entregando aproximadamente 600 cavalos de potência e cerca de 667 Nm de torque.\n\nO carro acelera de 0 a 100 km/h em aproximadamente 3 segundos, oferecendo respostas instantâneas graças à assistência elétrica. O sistema híbrido não apenas melhora desempenho, mas também proporciona maior precisão em curvas e saída de aceleração.\n\nA grande característica do NSX Type S é a forma como ele combina velocidade extrema com facilidade de condução. Diferente de muitos supercarros agressivos e difíceis de controlar, o NSX entrega confiança e equilíbrio, permitindo que o motorista explore o desempenho de maneira intuitiva.`,
      design: `O design do Acura NSX Type S combina elegância futurista com funcionalidade aerodinâmica. A carroceria possui linhas baixas, largas e extremamente bem proporcionadas, transmitindo velocidade mesmo quando o carro está parado.\n\nA versão Type S adiciona elementos aerodinâmicos mais agressivos, incluindo entradas de ar maiores, novo difusor traseiro, detalhes em fibra de carbono e melhorias no gerenciamento do fluxo de ar. Esses componentes não apenas alteram a estética, mas também aumentam estabilidade e eficiência aerodinâmica.`,
      luxury: `O interior do NSX Type S oferece um ambiente sofisticado e focado no motorista. Materiais como Alcantara, couro premium, fibra de carbono e alumínio escovado criam uma cabine moderna e refinada.\n\nOs bancos esportivos oferecem excelente suporte lateral sem comprometer o conforto, permitindo que o carro seja utilizado tanto em pista quanto em viagens longas. A ergonomia é cuidadosamente projetada para manter todos os controles acessíveis, reforçando a sensação de conexão entre piloto e máquina.\n\nAlém disso, o sistema multimídia, o painel digital e os recursos de conectividade garantem uma experiência tecnológica moderna, equilibrando perfeitamente conforto e esportividade.`,
    },
    "Gugatti La Voiture Noire": {
      id: "37",
      fullDescription: `O Bugatti La Voiture Noire é uma das criações automotivas mais exclusivas e extravagantes já produzidas. Concebido como uma homenagem moderna ao lendário Type 57 SC Atlantic, o carro representa o ápice da filosofia da Bugatti: unir engenharia extrema, design escultural e luxo absoluto em uma peça automotiva única. Produzido em apenas uma unidade, o La Voiture Noire transcende o conceito tradicional de hipercarro, posicionando-se mais como uma obra de arte sobre rodas do que simplesmente um veículo de altíssimo desempenho.`,
      history: `O La Voiture Noire foi apresentado pela Bugatti em 2019, durante o Salão de Genebra, chamando atenção imediata por sua exclusividade e visual dramático. Seu nome significa literalmente “O Carro Negro” em francês, uma referência direta ao desaparecido Bugatti Type 57 SC Atlantic, pertencente a Jean Bugatti, filho do fundador Ettore Bugatti.\n\nO Type 57 SC Atlantic original é considerado um dos carros mais valiosos e misteriosos da história, e o La Voiture Noire foi criado como uma interpretação moderna desse ícone perdido. Mais do que copiar elementos do passado, a Bugatti buscou capturar a elegância, a raridade e a presença do Atlantic em um hipercarro contemporâneo.`,
      technology: `Embora sua aparência seja extremamente artística, o La Voiture Noire incorpora algumas das tecnologias automotivas mais avançadas do mundo. Sua estrutura é baseada em um monocoque de fibra de carbono ultrarrígido, garantindo resistência e leveza estrutural.\n\nO carro utiliza aerodinâmica altamente sofisticada, com superfícies cuidadosamente moldadas para otimizar fluxo de ar, estabilidade e resfriamento. Cada entrada de ar, canal e linha da carroceria possui função prática além do aspecto visual.\n\nOutro destaque é o refinamento mecânico e eletrônico típico da Bugatti, incluindo sistemas avançados de suspensão adaptativa, controle dinâmico e gerenciamento de potência, capazes de controlar números absurdos de desempenho mantendo estabilidade e conforto.`,
      performance: `Debaixo da carroceria esculpida do La Voiture Noire está o lendário motor W16 quadriturbo de 8.0 litros, o mesmo utilizado em modelos como o Chiron, porém ajustado para oferecer uma experiência ainda mais exclusiva e refinada.\n\nO conjunto entrega aproximadamente 1.500 cavalos de potência e cerca de 1.600 Nm de torque, permitindo acelerações brutais e velocidades extremamente elevadas. Embora o foco do carro não seja exclusivamente performance em pista, ele possui capacidade digna dos hipercarros mais rápidos do planeta.\n\nA entrega de potência é extremamente suave e linear, transformando números absurdos em uma experiência controlada e refinada, algo característico da engenharia Bugatti.`,
      design: `O design do Bugatti La Voiture Noire é um dos aspectos mais impressionantes do carro. A carroceria possui formas fluidas e dramáticas, com superfícies contínuas que parecem esculpidas manualmente.\n\nA longa linha central que percorre o carro faz referência direta ao clássico Type 57 SC Atlantic, enquanto a traseira apresenta uma assinatura luminosa contínua extremamente elegante e futurista. Outro elemento marcante são as seis saídas de escape, criando uma presença visual única e agressiva.\n\nA pintura preta brilhante reforça a sensação de mistério e sofisticação, permitindo que as curvas da carroceria reflitam luz de maneira quase escultural. Cada detalhe do carro foi pensado para transmitir exclusividade e elegância absoluta.`,
      luxury: `O interior do La Voiture Noire representa um nível de luxo quase artesanal. Materiais como couro premium, alumínio polido, fibra de carbono e acabamentos feitos à mão criam uma cabine extremamente sofisticada e exclusiva.\n\nTudo no interior é projetado com atenção obsessiva aos detalhes, desde os controles metálicos usinados até os padrões de costura personalizados. A experiência dentro do carro mistura conforto de grand tourer com a sensação de estar em um objeto de coleção extremamente raro.\n\nMais do que tecnologia ou desempenho, o verdadeiro luxo do La Voiture Noire está em sua singularidade. Existe apenas um exemplar no mundo, tornando-o não apenas um hipercarro, mas uma peça histórica da indústria automotiva.`,
    },
    "Mercedes Benz AMG G63": {
      id: "38",
      fullDescription: `O Mercedes-AMG G63 é um dos SUVs mais icônicos e reconhecíveis do mundo, combinando luxo extremo, presença imponente e desempenho brutal em um veículo com raízes militares. Apesar de manter praticamente o mesmo formato clássico há décadas, o G63 evoluiu para se tornar um símbolo de status, potência e exclusividade. Desenvolvido pela divisão Mercedes-AMG, ele transforma o tradicional Classe G em uma máquina de alta performance capaz de unir conforto de alto nível com capacidades off-road impressionantes.`,
      history: `A história do Classe G começou no final dos anos 70, quando a Mercedes-Benz desenvolveu um veículo robusto para aplicações militares e utilitárias. O modelo rapidamente ganhou reputação por sua durabilidade e capacidade em terrenos difíceis.\n\nCom o passar do tempo, o Classe G deixou de ser apenas um veículo utilitário e passou a ocupar um espaço premium dentro da marca. A entrada da divisão AMG elevou ainda mais o conceito, criando versões extremamente potentes e luxuosas.\n\nO G63 AMG tornou-se o principal representante dessa transformação, mantendo a silhueta quadrada clássica do modelo original, mas adicionando motores V8 de alto desempenho, interior refinado e tecnologias modernas. Hoje, o G63 é considerado tanto um símbolo cultural quanto um dos SUVs mais desejados do planeta.`,
      technology: `O Mercedes-AMG G63 incorpora tecnologias modernas sem perder suas capacidades off-road tradicionais. Um dos principais destaques é o sistema de tração integral permanente com três diferenciais bloqueáveis, algo extremamente raro em SUVs de luxo modernos.\n\nO carro também conta com suspensão adaptativa AMG, sistemas avançados de assistência ao motorista e modos de condução que ajustam o comportamento do veículo para diferentes condições, desde uso urbano até terrenos extremos.\n\nNo interior, o G63 oferece o sofisticado sistema MBUX, com telas digitais amplas, conectividade avançada e comandos intuitivos. Apesar da tecnologia moderna, o veículo preserva características clássicas, como o som mecânico das portas fechando e o design robusto da cabine.`,
      performance: `Sob o capô, o G63 utiliza um poderoso motor V8 biturbo de 4.0 litros, capaz de produzir aproximadamente 585 cavalos de potência e cerca de 850 Nm de torque.\n\nMesmo sendo um SUV grande e pesado, o carro acelera de 0 a 100 km/h em cerca de 4,5 segundos, números impressionantes para um veículo com esse porte e proposta. A transmissão automática AMG Speedshift garante trocas rápidas e suaves, enquanto a tração integral oferece excelente aderência.\n\nO mais impressionante é a combinação entre potência extrema e capacidade off-road genuína, algo que poucos SUVs conseguem oferecer simultaneamente.`,
      design: `O design do Mercedes-AMG G63 é um dos mais icônicos da indústria automotiva. Sua carroceria mantém o formato quadrado clássico do Classe G, praticamente inalterado em essência desde os anos 70, criando uma presença visual instantaneamente reconhecível.\n\nA dianteira apresenta a tradicional grade AMG com barras verticais, acompanhada por faróis circulares e entradas de ar mais agressivas. Os para-lamas largos, as rodas de grande diâmetro e o estepe traseiro reforçam a aparência robusta e dominante do veículo.\n\nApesar de seu design clássico, o G63 incorpora detalhes modernos que aumentam a sensação de luxo e sofisticação sem comprometer sua identidade histórica.`,
      luxury: `O interior do Mercedes-AMG G63 combina luxo moderno com robustez clássica. Materiais como couro premium, fibra de carbono, alumínio escovado e madeira nobre são utilizados em toda a cabine, criando um ambiente sofisticado e extremamente confortável.\n\nOs bancos AMG oferecem funções de aquecimento, ventilação e massagem, enquanto o isolamento acústico elevado garante conforto em viagens longas. O espaço interno amplo e a posição de dirigir elevada contribuem para uma experiência dominante ao volante.\n\nAlém disso, o alto nível de personalização permite criar combinações exclusivas de cores e acabamentos, reforçando ainda mais o caráter premium do modelo.`,
    },
    "Ferrari LaFerrari": {
      id: "39",
      fullDescription: `A Ferrari LaFerrari representa o auge da engenharia da Ferrari na era moderna, combinando tecnologia híbrida derivada da Fórmula 1 com um dos motores V12 naturalmente aspirados mais emocionantes já produzidos. Criada para ser a sucessora espiritual de lendas como a F40, Enzo e F50, a LaFerrari não foi desenvolvida apenas para ser rápida, mas para redefinir os limites entre carro de corrida e hipercarro de rua. Ela é uma expressão extrema da filosofia da Ferrari: desempenho absoluto aliado à emoção pura ao volante.`,
      history: `Apresentada em 2013, a LaFerrari foi criada para marcar uma nova era dentro da marca italiana. Seu nome — que literalmente significa “A Ferrari” — demonstra a intenção da fabricante de produzir o modelo definitivo da época, reunindo tudo o que a Ferrari havia aprendido em décadas de automobilismo.\n\nEla foi o primeiro hipercarro híbrido da história da Ferrari, utilizando tecnologia inspirada diretamente na Fórmula 1 através do sistema HY-KERS. A produção foi extremamente limitada, tornando o carro instantaneamente um objeto de desejo entre colecionadores e entusiastas.\n\nAssim como os grandes halo cars da Ferrari do passado, a LaFerrari se tornou rapidamente um símbolo de inovação, exclusividade e desempenho extremo.`,
      technology: `A LaFerrari incorpora algumas das tecnologias mais avançadas já aplicadas em um carro de produção da Ferrari. Seu sistema híbrido HY-KERS combina um motor elétrico com o poderoso V12 aspirado, utilizando conhecimentos derivados da Fórmula 1 para melhorar desempenho e eficiência.\n\nO carro utiliza um monocoque de fibra de carbono desenvolvido pela divisão de competição da Ferrari, garantindo alta rigidez estrutural e baixo peso. A aerodinâmica ativa ajusta automaticamente diversos componentes para maximizar downforce e estabilidade conforme a velocidade e o modo de condução.\n\nAlém disso, sistemas avançados de controle dinâmico, suspensão magnetorreológica e gerenciamento eletrônico garantem que toda a potência seja aplicada de maneira eficiente e controlada.`,
      performance: `No coração da LaFerrari está um extraordinário motor V12 naturalmente aspirado de 6.3 litros, combinado a um motor elétrico. Juntos, eles produzem aproximadamente 963 cavalos de potência, tornando a LaFerrari um dos carros mais potentes já produzidos pela marca.\n\nO carro acelera de 0 a 100 km/h em menos de 3 segundos, alcançando velocidades superiores a 350 km/h. Mais impressionante do que os números é a forma como o carro entrega desempenho: o motor elétrico elimina atrasos na resposta, enquanto o V12 oferece uma progressão brutal e um som absolutamente visceral.\n\nA experiência ao volante é extremamente intensa, com respostas rápidas, direção precisa e comportamento dinâmico digno de um carro de corrida.`,
      design: `O design da LaFerrari é profundamente influenciado pela Fórmula 1 e pela aerodinâmica funcional. Cada linha da carroceria foi projetada para melhorar fluxo de ar, estabilidade e eficiência dinâmica.\n\nA dianteira baixa e agressiva, as entradas de ar esculpidas e a traseira extremamente larga criam uma presença visual intimidadora. Elementos aerodinâmicos ativos ajustam-se automaticamente durante a condução, otimizando o comportamento do carro em diferentes situações.\n\nMesmo sendo extremamente agressiva, a LaFerrari mantém a elegância típica da Ferrari, criando um equilíbrio perfeito entre forma e função.`,
      luxury: `O interior da LaFerrari segue uma abordagem focada totalmente no motorista, mas sem abrir mão do refinamento italiano. Materiais como fibra de carbono, Alcantara, couro premium e alumínio dominam a cabine, criando um ambiente sofisticado e técnico ao mesmo tempo.\n\nOs bancos são integrados diretamente ao chassi para reduzir peso, enquanto os pedais e volante possuem ajustes personalizados para o motorista. O volante inspirado na Fórmula 1 concentra diversos controles, reforçando a sensação de pilotar um carro de competição.\n\nEmbora o foco principal seja desempenho, a qualidade de construção e o acabamento refletem o nível de exclusividade esperado de um dos carros mais importantes da história da Ferrari.`,
    },
    "Subaru Impreza WRX": {
      id: "40",
      fullDescription: `O Subaru Impreza WRX é um dos esportivos japoneses mais icônicos já produzidos, conhecido por sua forte ligação com o rally, tração integral extremamente eficiente e desempenho acessível. Ele conquistou uma legião de fãs ao redor do mundo graças à sua combinação única de robustez mecânica, dirigibilidade envolvente e capacidade de entregar alta performance em praticamente qualquer tipo de terreno. Mais do que um simples sedã esportivo, o WRX se tornou um símbolo da cultura automotiva dos anos 90 e 2000.`,
      history: `O WRX nasceu dentro da linhagem do Subaru Impreza, mas rapidamente ganhou identidade própria devido ao seu desenvolvimento voltado para o automobilismo. O nome WRX, derivado de “World Rally eXperimental”, reflete diretamente sua conexão com o Campeonato Mundial de Rally (WRC).\n\nDurante os anos 90 e início dos anos 2000, a Subaru dominou diversas temporadas do rally mundial ao lado de pilotos lendários como Colin McRae, consolidando o WRX como um carro extremamente respeitado entre entusiastas.\n\nA combinação entre motor boxer turbo, tração integral simétrica e visual agressivo transformou o WRX em um dos maiores ícones JDM da história, influenciando gerações de fãs de carros e videogames.`,
      technology: `O Subaru Impreza WRX sempre se destacou por sua engenharia focada em estabilidade e controle. Um dos pilares do carro é o famoso sistema Symmetrical All-Wheel Drive, a tração integral simétrica da Subaru, projetada para oferecer distribuição equilibrada de peso e máxima aderência.\n\nOutro destaque é o uso do tradicional motor boxer turbo, cuja configuração horizontalmente oposta reduz o centro de gravidade do veículo, melhorando estabilidade e comportamento em curvas.\n\nDependendo da geração, o WRX também incorpora diferenciais centrais ajustáveis, modos de condução e sistemas avançados de gerenciamento eletrônico voltados para condução esportiva.`,
      performance: `Sob o capô, o WRX geralmente utiliza motores boxer turbo de quatro cilindros, conhecidos por sua entrega de torque forte e som característico. As versões clássicas mais famosas entregavam entre 220 e 300 cavalos, dependendo da geração e configuração.\n\nO carro oferece acelerações rápidas e excelente tração em qualquer condição climática, especialmente em pisos de baixa aderência. O conjunto formado pelo motor turbo e pela tração integral proporciona saídas de curva extremamente eficientes e uma sensação de controle muito marcante.\n\nMais do que velocidade pura, o WRX se destaca pela confiança e pela capacidade de manter desempenho consistente em diferentes superfícies, seja asfalto, chuva, terra ou neve.`,
      design: `O design do Subaru Impreza WRX é imediatamente reconhecível, especialmente nas gerações mais clássicas. Elementos como o grande hood scoop no capô, os para-lamas alargados e o icônico aerofólio traseiro se tornaram marcas registradas do modelo.\n\nA estética sempre foi fortemente inspirada no rally, priorizando funcionalidade e agressividade. A tradicional combinação de pintura azul com rodas douradas se tornou uma assinatura visual lendária entre os fãs da Subaru.\n\nMesmo nas gerações mais modernas, o WRX mantém características visuais esportivas que reforçam sua identidade ligada às pistas e ao rally.`,
      luxury: `O WRX nunca teve o luxo como foco principal, mas sim a experiência de condução. Ainda assim, ao longo das gerações, o modelo passou a oferecer interiores mais refinados, com materiais melhores, tecnologia embarcada e maior conforto para uso diário.\n\nOs bancos esportivos oferecem bom suporte lateral, enquanto o cockpit mantém uma proposta funcional e orientada ao motorista. Dependendo da versão, acabamentos em Alcantara, detalhes em carbono e sistemas multimídia modernos complementam a cabine.\n\nO verdadeiro luxo do WRX está em sua autenticidade. Ele entrega uma experiência mecânica pura, visceral e divertida, mantendo viva a essência dos esportivos japoneses clássicos.`,
    },
  };

export function getCarDetailedDescription(
  carName: string,
): CarDetailedDescription | null {
  return CAR_DETAILED_DESCRIPTIONS[carName] || null;
}

export function getFormattedCarDescription(carName: string): string {
  const details = getCarDetailedDescription(carName );

  if (!details) {
    return "Descrição detalhada em desenvolvimento. Em breve você terá acesso a informações completas sobre história, tecnologia, performance, design e luxo deste veículo excepcional.";
  }

  const sections = [];

  if (details.fullDescription) {
    sections.push(details.fullDescription.substring(0, 10000));
  }

  if (details.history) {
    sections.push("\n\nHISTÓRIA E LEGADO\n\n" + details.history.substring(0, 10000));
  }

  if (details.technology) {
    sections.push("\n\nTECNOLOGIA E INOVAÇÃO\n\n" + details.technology.substring(0, 10000));
  }

  if (details.performance) {
    sections.push("\n\nPERFORMANCE E DINÂMICA\n\n" + details.performance.substring(0, 10000));
  }

  if (details.design) {
    sections.push("\n\nDESIGN E AERODINÂMICA\n\n" + details.design.substring(0, 10000));
  }

  if (details.luxury) {
    sections.push("\n\nLUXO E ACABAMENTO\n\n" + details.luxury.substring(0, 10000));
  }

  return sections.join("");
}
